(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["4-2"] = [{"a": [33], "v": 3, "p": 1217, "ev": 3, "ep": 1221, "sid": 1418, "t": "قوله تعالى: (ولكل جعلنا موالي مما ترك الوالدان والأقربون والذين عقدت أيمانكم فآتوهم نصيبهم إن الله كان على كل شيء شهيدا (33)\nالمولى من الولاء، وهو تتابع الشيء من غير حائل.\nوجعل المولى لمن تولى حفظ الشيء، وتعورف في المعتق، والمعتق.\nوابن العم، والحليف، وولي الأمر، والعصبة،\n⟦3:1218⟧\nقال ابن عباس: هم الورثة ههنا، وقال مجاهد وقتادة: العصبة\nلقول النبي - صلى الله عليه وسلم -:\n\"من مات وترك مالا فماله للموالي العصبة، ومن ترك كلا فأنا وليه \".\nبين أن لكل مال تركه الوالدان والأقربون موالي يرثونه.\nوقوله: ﴿وَٱلَّذِينَ عَقَدَتۡ أَيۡمَٰنُكُمۡ﴾⟪4:33⟫ قيل: عنى به\n⟦3:1219⟧\nعقد الحلف، وكانت العرب تتوارث به، ثم نسخ بقوله:\n﴿وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ﴾\nوذلك عن ابن عباس والحسن وسعيد وقتادة.\nوقال أصحاب أبي حنيفة: الآية تقتضي أن المعاقدة يستحق بها الإرث.\nقالوا: ويقوي ذلك قوله: ﴿وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ﴾.\nفجعل ذوي الأرحام أولى من المعاقد، فدل ذلك أن المعاقد فيه حقا.\nقالوا: وروى تميم الداري أنه قال: يا رسول الله:\nما السنة في الرجل يسلم على يد مسلم؟\nفقال: \"هو أولى بمحياه ومماته \".\n⟦3:1220⟧\nوقيل: عنى الذين عقدت أيمانهم في الجاهلية، فجعل تعالى\nلهم نصيبا كنصيب الأخ من الأم، وسقط حكمهم بموتهم.\nوقيل: جعل لهم النصيب من النصرة دون الإرث.\nوقد روي ذلك عن ابن عباس ومجاهد وعطاء. قالوا:\nوحكم الأول قديم بقوله: (والأقربون).\nواستؤنف قوله: ﴿وَٱلَّذِينَ عَقَدَتۡ أَيۡمَٰنُكُمۡ﴾⟪4:33⟫\nقال ابن الحسن: عنى بالذين عاقدت أيمانكم: الأزواج لقوله تعالى:\n﴿وَلَا تَعۡزِمُواْ عُقۡدَةَ ٱلنِّكَاحِ﴾⟪2:235⟫\nقال: وصار المذكور في هذه الآية جملة ما فصله في آيات المواريث.\nفصار هذه الآية كقوله - صلى الله عليه وسلم -: \"إن الله أعطى كل ذي حق حقه \"،\n⟦3:1221⟧\nقال: والأيمان جمع اليمين التي هي الجارحة.\nوسمي الحلف بها اعتبارا بالصفقة في المبالغة."}, {"a": [34], "v": 3, "p": 1221, "ev": 3, "ep": 1226, "sid": 1422, "t": "قوله تعالى: (الرجال قوامون على النساء بما فضل الله بعضهم على بعض وبما أنفقوا من أموالهم فالصالحات قانتات حافظات للغيب بما حفظ الله واللاتي تخافون نشوزهن فعظوهن واهجروهن في المضاجع واضربوهن فإن أطعنكم فلا تبغوا عليهن سبيلا إن الله كان عليا كبيرا (34)\nالقنوت: القيام على وجه الطاعة، ويستعمل في كل واحد منهما.\nوالنشوز: بغض المرأة للزوج، وأصله من النشز.\nفكأنها هي المرتفعة بنفسها أو طرفها عن التزام ما يلزمها للزوج.\nوبهذا النظر قال الشاعر:\n⟦3:1222⟧\nإذا جلست عند الإمام كأنها. . . ترى رفقة من ساعة تستحيلها\nبين تعالى أن السياسة للرجل دون المرأة، وأن لكل واحد\nمن الرجل والمرأة فضيلتين: إحداهما: تسخير من الله تعالى.\nوالأخرى من كسبه، فإحدى فضيلتي الرجل: ما خصه به من علوه على\nالمرأة، والثانية: بإنفاق المال، وإحدى فضيلتي المرأة: قيامها بما يلزمها\nمن طاعة الأزواج، وحفظ غيبهم، وتحصين ما سلموه إليهن.\nوالثانية: إسبال الله ستر رحمته عليها وحفظها بوصية الزوج بها، وتسخيره\nللقيام بمراعاتها.\nوقرأ أبو جعفر المدني: \"بما حفظ الله\" بالنصب،\n⟦3:1223⟧\nأي فعل ذلك بهن بحفظهن الله، وجعل بما بمنزلة المصدر.\nوقوله: (واللاتي تخافون) قال بعض أهل اللغة: أي تعلمون.\nوأنشد:\nفلا تدفنني في الفلاة فإنني. . . أخاف إذا ما مت أن لا أذوقها\n⟦3:1224⟧\nوأرى قائل هذا تصور الظن بصورة العلم، فأطلق عليه اسمه.\nفأكثر الخوف مضمن بالظن.\nوقوله: (فعظوهن) تنبيه على أنها توعظ أولا، ثم تهجر، ثم تضرب.\nوهذا مقتضى حكمة السياسة، وعليه بني قول الشاعر:\nأناة فإن لم تغن عقب بعدها. . . وعيد فإن أتغن أغنت عزائمه\nوقوله: ﴿وَٱهۡجُرُوهُنَّ فِي ٱلۡمَضَاجِعِ﴾⟪4:34⟫ كالتصريح في الكناية عن الجماع.\nوقول من قال: هجر الكلام فليس بشيء،\n⟦3:1225⟧\nوقد قال - صلى الله عليه وسلم -:\n\"لا تهجروا النساء إلا في بيوتهن، ولا تهجروهن إلا في المضاجع.\nفإن أبين فاضربوهن ضربا غير مبرح \".\nوقوله: ﴿فَإِنۡ أَطَعۡنَكُمۡ﴾⟪4:34⟫ تنبيه على أن الذي يلزم هو بذل الطاعة في\nالظاهر.\nفأما المحبة بالقلب فليس من فعلها فتؤخذ به.\nونبه بقوله: ﴿إِنَّ ٱللَّهَ كَانَ عَلِيّٗا كَبِيرٗا﴾⟪4:34⟫ على أن الله تعالى مع هذه\nالحالة يقتصر من عباده في كثير من عبادتهم على الظاهر،\n⟦3:1226⟧\nوقيل: نبه أن لا يظن أحد الزوجين إن كلفه إلا الحق، فإنه يتعالى ويكبر\nعن الظلم."}, {"a": [35], "v": 3, "p": 1226, "ev": 3, "ep": 1228, "sid": 1427, "t": "قوله تعالى: (وإن خفتم شقاق بينهما فابعثوا حكما من أهله وحكما من أهلها إن يريدا إصلاحا يوفق الله بينهما إن الله كان عليما خبيرا (35)\nالشقاق: التعادي، ومنه قيل: شق فلان العصى، إذا تباعد في الخروج\nعن الطاعة، ومنه المشقة، وشق على فلان كذا .\nوالتوفيق كالمساواة، ومنه توفيق الله تعالى، فإنه موافقة قضائه فعل العبد\nفيما يقصده، ويقال الاتفاق في كل متطابقين على بعض الوجوه،\n⟦3:1227⟧\nولما بين تعالى من حال نشوزها ما يمكن للزوج إصلاحه، بين\nههنا ما يشتبه الحال فيه، واحتيج إلى ناظر فيما بينهما.\nوأكثر العلماء على أن المأمور ببعث الحكمين الإمام أو صاحبه.\nوإليه ذهب مالك، والأصم، وجعلوا للحاكم الطلاق والخلع\nكالوكيل، وإليه ذهب ابن عباس.\nومن الفقهاء من لم يجوز لهما الخلع والطلاق.\nفإن ظاهر الآية لم يقتضهما، ولا فرق\n⟦3:1228⟧\nبين أن يكون الحكمان من أقاربهما، أو من قبلهما.\nوقال ابن عباس: إرادتهما الإصلاح أن يخلو كل واحد\nمن الحكمين بأحد الزوجين، فيتعرف حاله في السر ليبني الأمر عليه.\nوفي الآية دلالة على أن كل أمر وقع فيه تنازع يجوز فيه التحكيم.\nوبهذه الآية استدل في أمر الحكمين.\nونبه بقوله: ﴿إِن يُرِيدَآ إِصۡلَٰحٗا يُوَفِّقِ ٱللَّهُ بَيۡنَهُمَآۗ﴾⟪4:35⟫ أن من أصلح نيته في أمر يتحراه أصلح الله مبتغاه، كما روي في الخبر أن \"من أصلح سريرته أصلح الله علانيته \".\nوقيل: إذا فسدت النية وقعت البلية."}, {"a": [36], "v": 3, "p": 1228, "ev": 3, "ep": 1235, "sid": 1429, "t": "قوله تعالى: (واعبدوا الله ولا تشركوا به شيئا وبالوالدين إحسانا وبذي القربى واليتامى والمساكين والجار ذي القربى والجار الجنب والصاحب بالجنب وابن السبيل وما ملكت أيمانكم إن الله لا يحب من كان مختالا فخورا (36)\nالجار اعتبارا بكونه من ناحية دارك، من قولهم: جار\nعن الطريق، ثم جعل أصلا في بابه، فقيل: استجرت فلانا\n⟦3:1229⟧\nوآجرته. إذا رعيته مراعاة الجار.\nوالجنب أصله في الجارحة، ثم قيل في المكان اعتبارا به.\nفقيل: جنبته إذا أخذته في ناحية\nالجنب، واجتنب عنه إذا تركه وتباعد عنه.\nوالأجنبي: الغريب، والجنابة: الاعتزال والتباعد.\nومنه قيل للحالة المقتضية لترك الصلاة: جنابة.\nوالجار ذي القربى والجار الجنب: قيل: عنى به قرب الرحم وبعده.\nوقيل: عنى به قرب المسافة\n⟦3:1230⟧\nوبعدها، والصاحب بالجنب: قيل: جار البيت، دانيا كان نسبه\nأو نائيا.\nوقيل: هو الرفيق في السفر، وقيل: هو المنقطع إليك\nرجاء خيرك، وقيل: المرأة.\n﴿وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ﴾⟪4:36⟫\nقيل : وقد أمر بالإحسان إليهم، وأن لا يكلفوا ما لا يطيقون،\n⟦3:1231⟧\nإن قيل: لم قدم الأمر بالإيمان على النهي عن الشرك.\nومعلوم أن تجنب الشرك مقدم على حقيقة الإتيان با لإيمان؟\nقيل: إن الشرك يقال على ضربين:\nأحدهما: الشرك الأكبر، وهو إثبات صانع غير الله.\nوالثاني: الرياء، وإياه\n⟦3:1232⟧\nعنى النبي - صلى الله عليه وسلم - فيما روى شداد بن أوس أن النبي - صلى الله عليه وسلم - قال:\n\"أمران أتخوفهما على أمتي من بعدي: الشرك، والشهوة الخفية.\nألا إنهم لا يعبدون شمسا ولا قمرا، ولكنهم يراءون \".\nفقلت: أشرك ذلك؟ قال: \" نعم \"، وإياه عنى تعالى بقوله: ﴿فَمَن كَانَ يَرۡجُواْ لِقَآءَ رَبِّهِۦ فَلۡيَعۡمَلۡ عَمَلٗا صَٰلِحٗا﴾⟪18:110⟫ الآية.\nإن قيل: لم ذكر ههنا تسعة أصناف وأمر بالتوفر عليهم.\nوذكر في سورة البقرة: ﴿وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَانٗا وَذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ﴾⟪2:83⟫\n⟦3:1233⟧\nوقال بعده: ﴿وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ﴾⟪2:177⟫؟\nقيل: إن المذكور أولا في سورة البقرة ما أمر به بني إسرائيل.\nوأما قوله: ﴿وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ﴾⟪2:177⟫ فهو أمر بإيتاء المال الذي\nيقتضيه البر، لأنه قال: ﴿وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ﴾⟪2:177⟫، وهذه الآية\nحت على فعل الإحسان كله، نصرة كان أو صلة.\nوقيل: إن قوله: ﴿وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ﴾⟪2:177⟫ عنى المال كله على سبيل التبرع.\nوذلك إذا طلب الإنسان غاية البر، ولهذا قال الشعبي: ما\nبقى قول الله: ﴿وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ﴾⟪2:177⟫ على\n⟦3:1234⟧\nأحد شيئا من المال، ولإرادة إخراج المال كله على التبرع خص\nالزكاة بعده بالذكر، فقال: ﴿وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ﴾.\nوأراد بهذه الآية ما يحصل للإنسان به تمام العبادة.\nوفعل الإحسان. وذلك لعبادة الله المتعرية عن الرياء، ومراعاة هؤلاء بالإحسان.\nفإن قيل: لم قدم الجار على ابن السبيل وله حق واجب في المال؟\nقيل: ابن السبيل الذي له حق في المال هو الفقير، ولم يقصده بهذه\nالآية، وإنما المقصود تفقد المذكورين على سبيل التبرع، وحق\nالجار أوكد من حق الغرباء. ألا ترى أن النبي - صلى الله عليه وسلم -\nقال : \"ما زال جبريل يوصيني بالجار حتى ظننت أنه يورثه \"؟\nإن قيل: كيف قال: ﴿إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخۡتَالٗا فَخُورًا﴾⟪4:36⟫؟\n⟦3:1235⟧\nقيل: المختال هو الذي يظن أن له بماله كرما، من قولهم: خلت، وكأنما\nإلى معناه أشار تعالى بقوله: (الذي جمع مالا وعدده (2) يحسب أن ماله أخلده (3).\nوالفخور: من يتبجح بالقنيات الزائلة، فبين تعالى أن من أمسك ماله، وصرفه عن الوجوه المذكورة فذلك لظنه أن له بماله خيلاء وفخرا فيضن به، ويبين أن هذين سبب البخل ما روي:\n\"أهلك الناس شيئان: حب الفخر، وخوف الفقر \".\nولهذا عقبه بقوله تعالى: ﴿ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِ﴾⟪4:37⟫ الآية.\nفجعل تفسير الاحتيال والفخر البخل بالمال، والإنفاق على وجه الرياء."}, {"a": [37], "v": 3, "p": 1235, "ev": 3, "ep": 1238, "sid": 1436, "t": "قوله تعالى: (الذين يبخلون ويأمرون الناس بالبخل ويكتمون ما آتاهم الله من فضله وأعتدنا للكافرين عذابا مهينا (37)\n⟦3:1236⟧\nالبخل: أعظم المعايب، لقوله - صلى الله عليه وسلم -:\n\"أي داء أدوى من البخل؟ \"\nوأعظم منه حث الغير عليه، وكأن الشاعر بهذه الآية ألم في قوله:\nوإن امرأ ضمنت يداه على امرئ. . . بنيل يد من غيره لبخيل\nوقالوا: فلان يمنع دره ودر غيره، والحر يعطي والعبد يألم\nقلبه، ولم يرد تعالى بالبخل البخل بالمال فقط، بل بجميع ما منه\nنفع الغير، من نصرة وعلم، ودخل في عموم الأمر بالبخل: من\nترك شكر من أحسن إليه، أو أخل بقضاء دين فيصير سببا لمنع\nالإسداء إلى الغير، ولهذا قيل: لعن الله قاطعي المعروف.\nوقال بعضهم: معناه يبخلون ويتأمرون على الناس، ويأمرونهم\n⟦3:1237⟧\nبشكرهم مع بخلهم، فيكون قوله (بالبخل) في موضع الحال.\nوإلى هذا أشار الشاعر بقوله:\nجمعت أمرين ضاع الحزم بينهما. . . تيه الملوك وأفعال المماليك\nوقوله: (ويكتمون ما آتاهم الله من فضله.\nيدخل فيه من يستحقر ما آتاه الله من نعمته مالا كان أو عافية، ومن\nخول علما ولم يفده مقتبسه منه، ومن ينسى كثير ما أنعم الله\nعليه ويتذكر قليل ما يناله من نائبة، كقوله تعالى: ﴿إِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٞ﴾⟪100:6⟫ قيل في تفسيره: ينسى النعم وي) كر\nالمحن، ونبه بقوله: ﴿وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ﴾⟪4:37⟫ أن من\n⟦3:1238⟧\nفعل ذلك فهوكافر للنعمة، ومن كفر نعمة الله فقد أعد له عذابا."}, {"a": [38], "v": 3, "p": 1238, "ev": 3, "ep": 1239, "sid": 1439, "t": "قوله تعالى: (والذين ينفقون أموالهم رئاء الناس ولا يؤمنون بالله ولا باليوم الآخر ومن يكن الشيطان له قرينا فساء قرينا (38)\nذم في هذه الآية السرف، كما ذم في الأولى البخل.\nفمن السرف أن يتشبع الإنسان بإنفاقه، فلا ينفقه على ما يجب.\nوكما يجب فصار الإتيان كقوله تعالى: ﴿وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا﴾⟪25:67⟫\nوليس يعني بقوله: ﴿وَلَا يُؤۡمِنُونَ بِٱللَّهِ﴾⟪4:38⟫ جحود ذلك باللسان فقط، بل عنى معه ترك ما تقتضيه هذه المعرفة، تنبيها أن المنفق رياء لو كان له حقيقة إيمان\nلتذكر في تناول ما يتناوله، ولأداه ذلك إلى أن يتفكر أين يضعه،\n⟦3:1239⟧\nفإن قيل: فأي تعلق لقوله: ﴿وَمَن يَكُنِ ٱلشَّيۡطَٰنُ لَهُۥ قَرِينٗا﴾⟪4:38⟫\nقيل: هذا الكلام فيه إيجاز، كأته قيل: الذين ينفقون أموالهم\nرياء الناس زين لهم الشيطان الذين هم قرناؤهم ﴿وَمَن يَكُنِ ٱلشَّيۡطَٰنُ لَهُۥ قَرِينٗا﴾⟪4:38⟫ كقوله تعالى: ﴿إِنَّ ٱلۡمُبَذِّرِينَ كَانُوٓاْ إِخۡوَٰنَ ٱلشَّيَٰطِينِۖ﴾⟪17:27⟫، وعلى ذلك قوله: ﴿وَمَن يَعۡشُ عَن ذِكۡرِ ٱلرَّحۡمَٰنِ نُقَيِّضۡ لَهُۥ شَيۡطَٰنٗا فَهُوَ لَهُۥ قَرِينٞ﴾⟪43:36⟫\nولم يعن بالشيطان إبليس فقط، بل عناه والهوى.\nوكل ما دعاه إلى باطل، وصرفه عن حق."}, {"a": [39], "v": 3, "p": 1239, "ev": 3, "ep": 1240, "sid": 1440, "t": "وقوله: ﴿وَمَاذَا عَلَيۡهِمۡ﴾⟪4:39⟫ في قوله: ﴿وَمَاذَا عَلَيۡهِمۡ﴾⟪4:39⟫ استدعاء\nلطيف إلى تحري الإيمان والإنفاق على ما يجب، لأن لفظه استخبار\nيستدعي جوابا، ولا يمكن جواب المستخبر عنه المشتبه إلا بعد\nالتفكر فيه، والتفكر فيما ذكره تعالى يؤدي إلى أن ليس على\n⟦3:1240⟧\nمتحري ذلك ضير، بل له كل خير.\nإن قيل: لم قدم الإنفاق في الآية الأولى وأخره ههنا؟ قيل: لما\nقصد في الأولى إلى ذمهم بالإنفاق رياء لكونهم غير مؤمنين، قدم\nذكره، وجعل قوله: ﴿وَلَا يُؤۡمِنُونَ﴾⟪4:38⟫ في مو ضع الحال تنبيها أن\nذلك منهم لكونهم غير مؤمنين، ولما حثهم في هذه الآية على ما يجب\nأن يتحروه ابتدأ بذكر الإيمان، تنبيها أن إنفاقهم غير معتد به إلا\nبعد الإيمان بهما."}, {"a": [40], "v": 3, "p": 1240, "ev": 3, "ep": 1244, "sid": 1441, "t": "قوله تعالى: (إن الله لا يظلم مثقال ذرة وإن تك حسنة يضاعفها ويؤت من لدنه أجرا عظيما (40)\nعنى بالظلم\n⟦3:1241⟧\nههنا بخس الحق ومثقال: مفعال: من الثقل، وضرب تعالى\nالذر مثلا للشيء الصغير، تقريبا على المخاطب.\nواستعمل لفظ المثقال تنبيها أن ذلك يعظم جزاؤه وإن صغر قدره.\nوفي قراءة ابن مسعود: مثقال نملة. وإذا قرئ (حسنة) بالنصب فتقديره: إن\nتكن الذرة حسنة، ورد الضمير إلى المضاف إليه دون المضاف.\nوإذا رفع فمعناه: إن تقع حسنة، ولا تحتاج كان ههنا إلى\n⟦3:1242⟧\nخبر، ويضاعف ويضعف يتقاربان.\nوقال القتيبي: يضاعف للمرة ويضعف للتكثير، وقد قال\n⟦3:1243⟧\nتعالى: ﴿مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ عَشۡرُ أَمۡثَالِهَاۖ﴾⟪6:160⟫، وقال: ﴿أَضۡعَافٗا كَثِيرَةٗۚ﴾⟪2:245⟫\nو (أضعافا مضاعفة).\nوفائدة قوله: ﴿مِن لَّدُنۡهُ﴾⟪4:40⟫ أن كل ما أريد تعظيمه ينسب إلى\nالله، فيقال: ﴿مِنۡ عِندِ ٱللَّهِۖ﴾، و (من لدنه)، و (له).\nو (بيت الله)، و (ناقة الله)، وعلى هذا قوله تعالى:\n﴿فَهَبۡ لِي مِن لَّدُنكَ وَلِيّٗا﴾⟪19:5⟫، ووصف الأجر بالعظيم اعتبار\nبالأجور الدنيوية.\n⟦3:1244⟧\nتقديره: كيف حالهم في ذلك الوقت استعظاما لأمرهم؟!"}, {"a": [41], "v": 3, "p": 1244, "ev": 3, "ep": 1246, "sid": 1445, "t": "وقوله: ﴿وَجِئۡنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدٗا﴾⟪4:41⟫ فيه أقوال:\nأحدها: أنه أشار إلى أمته، ويكون قوله: ﴿مِن كُلِّ أُمَّةِۭ بِشَهِيدٖ﴾⟪4:41⟫ عاما.\nوخص النبي - صلى الله عليه وسلم - وأمته بالذكر تعظيما لهم.\nوالثاني: ما قاله ابن عباس: إن هذه الأمة تشهد للأنبياء، والنبي\n- صلى الله عليه وسلم - يشهد لأمته تزكية لهم.\nواستدل بقوله: ﴿لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدٗاۗ﴾⟪2:143⟫.\nوالثالث: إن قوله: ﴿عَلَىٰ هَٰٓؤُلَآءِ﴾⟪4:41⟫\n⟦3:1245⟧\nإشارة إلى الأنبياء الذين هم الشهداء على أممهم.\nإن قيل: كيف يصح أن يكون النبي - صلى الله عليه وسلم - شاهدا للأنبياء الذين قبله وهو لم يحضرهم؟ وأي فائدة لشهادته وشهادتهم؟\nقيل: إن الأنبياء لم يختلفوا في أصول ما دعوا إليه.\nبل كلهم لسان واحد في الدعاء إلى التوحيد.\nوأصول الاعتقادات والعبادات، وسائر جمل الشريعة.\nوعلى ذلك نبه بقوله تعالى: ﴿شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحٗا وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَمَا وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ أَنۡ أَقِيمُواْ ٱلدِّينَ وَلَا تَتَفَرَّقُواْ فِيهِۚ﴾⟪42:13⟫ الآية.\nوكل واحد منهم معتقد لما اعتقده الآخر، ومبلغ ذلك مثل ما بلغه الآخر.\nثم شريعة النبي - صلى الله عليه وسلم - جامعة لأصول شرائع من تقدمه، ولذلك قيل له: خاتم الأنبياء، وعليه نبه - صلى الله عليه وسلم - بقوله: \"مثلي ومثل الأنبياء كمثل رجل بنى بيتا، وترك موضع لبنة منه، فكنت موضع اللبنة\"،\n⟦3:1246⟧\nوبهذا المعنى ألم بعض المحدثين فقال:\nنسقوا لنا نسق الحساب مقدما. . . وأتى فذلك إذ أتيت مؤخرا\nوأما فائدة إقامتها عليهم فتبكيت للعاصين، وتشنيع عليهم.\nوتزكية للمؤمنين، على ما ذكر في قوله: ﴿بَلِ ٱللَّهُ يُزَكِّي مَن يَشَآءُ﴾⟪4:49⟫."}, {"a": [42], "v": 3, "p": 1246, "ev": 3, "ep": 1249, "sid": 1447, "t": "وقوله: (يومئذ يود الذين كفروا وعصوا الرسول لو تسوى بهم الأرض ولا يكتمون الله حديثا (42)\nمنهم من جعل الصفتين لفريق واحد، أي الذين جمعوا بين الكفر ومخالفة\nالأمر، ومنهم من جعلهما وصفين لفريقين، أي الذين كفروا\nوعصوا الرسول؛ فالأول للكفار، والثاني لأهل الكبائر،\n⟦3:1247⟧\nوقوله: ﴿لَوۡ تُسَوَّىٰ بِهِمُ ٱلۡأَرۡضُ﴾⟪4:42⟫ أي تمنوا أن لم يبعثوا من القبور.\nوقيل: أن جعلوا ترابا كالبهائم، وقيل: أن لم يخلقوا رأسا.\nونحوه قوله تعالى: ﴿وَيَقُولُ ٱلۡكَافِرُ يَٰلَيۡتَنِي كُنتُ تُرَٰبَۢا﴾⟪78:40⟫،\n⟦3:1248⟧\nوقوله: ﴿لَوۡ تُسَوَّىٰ﴾⟪4:42⟫ بتشديد السين على إدغام التاء في السين.\nوتسوى بالتخفيف على حذف إحدى التاءين.\nوقوله: ﴿وَلَا يَكۡتُمُونَ ٱللَّهَ حَدِيثٗا﴾⟪4:42⟫ قيل: فيه أقوال:\nأحدها: ما روي عن ابن عباس وقد سئل عن هذه الآية.\nوقوله: ﴿وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشۡرِكِينَ﴾⟪6:23⟫ فقال:\nإن المشركين يوم القيامة لما رأوا أن لا يدخل الجنة إلا من كان مسلما.\nقال بعضهم لبعض: تعالوا نجحد، نقول: ما كنا مشركين.\nفلما قالوا ذلك ختم الله على ألسنتهم، وتكلمت جوارحهم، فشهدت\nعليهم، فودوا لو ساخت بهم الأرض ولا يكتمون الله.\n⟦3:1249⟧\nوالثاني: ما قاله الحسن: إن الآخرة مواقف، وفي بعضها يظهرون.\nوروي عنه أن في بعضها لا يتكمون.\nوالثالث: أنهم لا يكتمون الله حديثا، لنطق جوارحهم بذنوبهم.\nفعلى هذا لا يكون قوله: ﴿وَلَا يَكۡتُمُونَ﴾⟪4:42⟫ داخلا في التمني.\nبل هو استئناف كلام.\nوالرابع: أنه لم يقصد بقوله: ﴿وَلَا يَكۡتُمُونَ﴾⟪4:42⟫ أنهم لا يقصدون كتمانه.\nبل عنى أنه لا يتكتم، وذلك كقولك لمن كتم عنك شيئا\nفاطلعت عليه: لم تكتم أسرارك عني.\nوالخامس: أن ذلك داخل في التمني، ولكن إشارة إلى حالهم في الدنيا وجحودهم، فإن كفرهم جحود لما ركز الله تعالى في فطرتهم.\nونقض لما أخذ عليهم من الميثاق المدلول عليه بقوله: ﴿وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ﴾⟪7:172⟫."}, {"a": [43], "v": 3, "p": 1250, "ev": 3, "ep": 1257, "sid": 1451, "t": "قوله تعالى: (يا أيها الذين آمنوا لا تقربوا الصلاة وأنتم سكارى حتى تعلموا ما تقولون ولا جنبا إلا عابري سبيل حتى تغتسلوا وإن كنتم مرضى أو على سفر أو جاء أحد منكم من الغائط أو لامستم النساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وأيديكم إن الله كان عفوا غفورا (43)\nالسكر: هو من السكر، أي سد مجرى الماء، وذلك لسد البخار\nالصاعد من المعدة قوة الفهم، وسكرت الريح:\nأي سكنت، تشبيها بسكون الماء إذا سد مجراه، وكذلك سكرت\nأبصارنا: أي سد مجراها، والسكر قد يقال لما يعرض من الهوى\nوالشباب والغنى.\nقال الشاعر:\nسكران سكر هوى وسكر شراب.\n⟦3:1251⟧\nويقال: سكارى وسكرى.\nوالغائط: المنهبط من الأرض فكنى به عن الحدث؛ كالنجو\nفي كونه للمرتفع من الأرض.\nوالعذرة للفناء، والحش للبستان، والكنيف للحظيرة.\nوالصعيد كالصعود، لكن الصعيد يقال لوجه الأرض.\n⟦3:1252⟧\nوالصعود للعقبة، ولما كان الصعيد يقال لوجه الأرض وللساطع منه.\nاختلف الفقهاء لاختلاف نظرهم في أنه هل يجب أن يعلق باليد\nشيء من التراب أم لا؟\nفجوز الكوفيون أن لا يعلق باليد شيء من الأرض.\nلكون الصعيد اسما لوجه الأرض.\nولم يجوز الحجازيون ذلك اعتبارا بالصعود.\nولقوله: ﴿فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُمۡۗ﴾⟪4:43⟫\nوكذلك اختلفوا في أنه هل يجوز التيمم بما يخرج من الأرض\nسوى التراب كالخل والزرنيخ؟\nفجوز ذلك بعضهم ومنع منه آخرون.\nفمن جوزه قال: لأن الصعيد اسم لما تصاعد من الأرض.\nوالتيمم والتأمم: \" التعمد، وفي قراءة عبد الله \"فتأمموا\".\n⟦3:1253⟧\nو (عابري سبيل): قال علي وابن عباس: هم المسافرون.\nقالوا: ويجوز لهم التيمم عند الجنابة.\nوالصلاة عندهما اسم الفعل.\nوقال الحسن وسعيد: عابر السبيل: المجتاز.\nوالصلاة يريد به موضعها، كقوله: ﴿لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعٞ وَصَلَوَٰتٞ﴾⟪22:40⟫.\n⟦3:1254⟧\nوالمريض الذي جوز له التيمم: الجريح والقريح دون المحموم والمصدع. والملامسة: الجماع، عن علي وعن ابن عباس.\nوقيل: اللمس\n⟦3:1255⟧\nباليد وما دون الجماع؛ عن ابن مسعود، وابن عمر.\nوقرئ: \"لمستم\"، والأول في الجماع أكثر.\nوقوله: ﴿لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ﴾⟪4:43⟫ ليس بنهي للسكران عن قربان الصلاة، كما تصوره بعض الناس فأطال فيه الكلام.\nوقال: كيف يصح نهي من لا يعقل ما يقول، وإنما ذلك نهي المؤمنين عن السكر المانع\n⟦3:1256⟧\nمن الصلاة، كقوله تعالى: ﴿وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ﴾⟪3:102⟫.\nوقيل: إن ذلك نهي عن الشرب، وكان هذا تعريضا بالتحريم.\nفلما أنزل الله ذلك تحرج قوم فتركوها، وشربه قوم في غير\nأوقات الصلوات إلى أن ورد تصريح التحريم.\nوقال بعض أهل الورع: ليس النهي عن تعاطي الخمر.\nبل ذلك عنه، وعن مقتضى سكر الهوى.\nوسكر الاشتغال بالدنيا، وأمر بأن يجمع الإنسان\n⟦3:1257⟧\nنفسه ويفرغ للعبادة همه، قال: وليست الجنابة للحالة المعروفة\nفقط، بل هي عبارة عن نجاسة النفس بالذنوب، وحث على\nتجنبها وتطهير النفس منها بقوله: (ليطهركم).\nفإن قيل: فما وجه تعلق هذه الآية بما قبلها.\nوالإتيان بحكم التيمم عقب ما تقدم؟\nقيل: لما أمر فيما تقدم بالعبادة بقوله: ﴿وَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ﴾⟪4:36⟫ وأعظم العبادة الصلاة، ولا تصح بغير طهارة بين عقيبها حكم ما يطهر، وحكم ما ينوب منابه إذا فقد."}, {"a": [44], "v": 3, "p": 1257, "ev": 3, "ep": 1258, "sid": 1458, "t": "قوله تعالى: (ألم تر إلى الذين أوتوا نصيبا من الكتاب يشترون الضلالة ويريدون أن تضلوا السبيل (44)\nرأيت: يعدى بإلى تنبيها على معنى النظر والاعتبار.\nوذلك في رؤية القلب دون الحاسة.\nواشتراء الضلالة بالهدى:\n⟦3:1258⟧\nاستبدالها به بغد حصوله، والرغبة في الضلالة بعد التمكن من\nالهدى، وقد أعاد تعالى هذا المعنى في مواضع تحذيرا منهم.\nوتخويفا من الاغترار بهم، وعلى ذلك قوله من قبل: ﴿وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُواْ مَيۡلًا عَظِيمٗا﴾⟪4:27⟫.\nونحوه قوله: ﴿وَلَا تَتَّبِعُوٓاْ أَهۡوَآءَ قَوۡمٖ قَدۡ ضَلُّواْ مِن قَبۡلُ وَأَضَلُّواْ كَثِيرٗا وَضَلُّواْ عَن سَوَآءِ ٱلسَّبِيلِ﴾⟪5:77⟫"}, {"a": [45], "v": 3, "p": 1258, "ev": 3, "ep": 1259, "sid": 1459, "t": "وقوله: (والله أعلم بأعدائكم وكفى بالله وليا وكفى بالله نصيرا (45)\nظاهره كالبعيد من الأول، وكذلك قوله: ﴿وَكَفَىٰ بِٱللَّهِ﴾⟪4:45⟫ وذلك\nلتحري الاختصار فيه، وتقدير الكلام: يريدون أن تضلوا السبيل.\nوإذا أرادوا ذلك فهم أعداؤكم، والله أعلم منكم بعداوتهم لكم.\nوهو تعالى وليكم ونصيركم، فإذن الواجب عليكم أن تتركوا\n⟦3:1259⟧\nموالاتهم، واستنصارهم، وتستكفوا بولاية الله ونصرته، وكفى\nبه وليا ونصيرا."}, {"a": [46], "v": 3, "p": 1259, "ev": 3, "ep": 1262, "sid": 1460, "t": "قوله تعالى: (من الذين هادوا يحرفون الكلم عن مواضعه ويقولون سمعنا وعصينا واسمع غير مسمع وراعنا ليا بألسنتهم وطعنا في الدين ولو أنهم قالوا سمعنا وأطعنا واسمع وانظرنا لكان خيرا لهم وأقوم ولكن لعنهم الله بكفرهم فلا يؤمنون إلا قليلا (46)\nاللي: أصله الفتل فاستعير لصرف الإنسان عما يريده، وصرف الكلام من\nوجه إلى وجه استعارة الجدل في الجدال، ومنه لي الغريم، ولواء الجيش\nلكونه في الأصل خيطا ملويا.\nواللوى: الملوئ من الرمل؛ لا يصنعه البشر.\nوقوله: (بألسنتهم) أي جارحتهم أوكلامهم، وكلا هما في\nالحقيقة واحد ﴿وَطَعۡنٗا فِي ٱلدِّينِۚ﴾⟪4:46⟫ أي يطعنون بألسنتهم في الدين،\n⟦3:1260⟧\nوقوله ﴿غَيۡرَ مُسۡمَعٖ﴾⟪4:46⟫ يقال على وجهين:\nأحدهما: دعاء على الإنسان بالصمم.\nوالثاني: دعاء له، فقد تعورف قوله: أسمعته؛ في السب.\nوروي أن أهل الكتاب كانوا يقولون ذلك.\nيرون أنهم يعظمون النبي، وأنهم يدعون له، لأن قولهم (سمعنا وعصينا) يقتضي ظاهره: أنا قد عصينا من أمرتنا بعصيانه.\nواسمع غير مشتوم؛ وحافظنا، وهم يقصدون بقولهم\n(وعصينا) أنا عصيناك، واسمع لا سمعت، وراعنا أي\nراعنا، وذلك شتم فيما بينهم، فذكر تعالى أن ذلك لي\n⟦3:1261⟧\nوطعن في الدين بألسنتهم، أي لغتهم، ولو عدلوا عن هذه\nالألفاظ إلى ما أمروا به لكان أنفع لهم، ولكن لما كفروا لعنهم\nالله، أي منعهم التوفيق وشرح الصدر، وقد تقدم معنى\nاللعنة وتفسير قوله: ﴿فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا﴾⟪4:46⟫.\nوقوله: ﴿مِّنَ ٱلَّذِينَ هَادُواْ﴾⟪4:46⟫ فيه قولان:\nالأول: أنه متعلق بما تقدم، كأنه قال:\nألم تر إلى الذين أوتوا نصيبا من الكتاب من الذين هادوا فيكم.\nفتكون (من) للجنس أو للتبيين، وتكون للوقف على قوله:\n﴿مِّنَ ٱلَّذِينَ هَادُواْ﴾⟪4:46⟫.\nوالثاني: أن تكون استئنافا على تقدير:\nمن الذين هادوا فريق، كقوله: ﴿وَمَا مِنَّآ إِلَّا لَهُۥ مَقَامٞ مَّعۡلُومٞ﴾⟪37:164⟫.\n⟦3:1262⟧\nواستقبح المبرد هذا الوجه لحذف الموصول وترك الصلة."}, {"a": [47], "v": 3, "p": 1262, "ev": 3, "ep": 1265, "sid": 1463, "t": "قوله تعالى: (يا أيها الذين أوتوا الكتاب آمنوا بما نزلنا مصدقا لما معكم من قبل أن نطمس وجوها فنردها على أدبارها أو نلعنهم كما لعنا أصحاب السبت وكان أمر الله مفعولا (47)\nالطمس والطلس والدرس يتقارب، ولكن الطمس زوال\nالأعلام المماثلة، قال: وبلدة طامسة أعلامها، والطلس زوال\nالصورة، ومنه قيل: درهم مطلس، إذا لم يكن عليه نقش، والدرس\nقد يقال في الأثر الخفي.\nوطمس الوجوه منهم من أخذه\n⟦3:1263⟧\nمحسوسا ثم اختلفوا؛ فمنهم من قال: عنى ذلك في الدنيا، وهو\nأن ينبت الشعر على وجوههم فتصير صورتهم كصورة القردة\nوالخنازير، وتكون وجوههم إلى أقفائهم، ومنهم من قال:\nعنى ذلك في الآخرة، وعلى ذلك قوله: ﴿وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ وَرَآءَ ظَهۡرِهِۦ﴾⟪84:10⟫، لأن وجوههم التي فيها العيون إلى ظهورهم.\nومنهم من أخذه معقولا، ثم اختلفوا: كيف يكون ذلك؟\nفمنهم من قال: عنى أنا نردهم عن الهداية إلى الضلالة لما ارتكبوه من المعاصي،\n⟦3:1264⟧\nنحو قوله: ﴿وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلۡمٖ وَخَتَمَ عَلَىٰ سَمۡعِهِۦ وَقَلۡبِهِۦ﴾⟪45:23⟫ الآية.\nوالثاني: أن تكون الوجوه الأعيان والرؤساء.\nوالمعنى قيل: أن يجعل الرؤساء منكم أذنابا.\nوعلى ذلك قوله تعالى: ﴿إِن تُطِيعُواْ ٱلَّذِينَ كَفَرُواْ يَرُدُّوكُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ﴾⟪3:149⟫ الآية.\nوقيل: إن ذلك في الآخرة، وهو أن قوما من الكفار كانوا\nيسخرون في الدنيا من المؤمنين، فيعرضون على الجنة ثم يردون على\nأعقابهم فيدخلون النار.\nوقوله: ﴿أَوۡ نَلۡعَنَهُمۡ كَمَا لَعَنَّآ أَصۡحَٰبَ ٱلسَّبۡتِۚ﴾⟪4:47⟫ إشارة إلى ما تقدم ذكره في قوله: ﴿وَلَقَدۡ عَلِمۡتُمُ ٱلَّذِينَ ٱعۡتَدَوۡاْ مِنكُمۡ فِي ٱلسَّبۡتِ﴾⟪2:65⟫ في سورة البقرة.\n⟦3:1265⟧\n﴿وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولًا﴾⟪4:47⟫\nأي نافذا في حكم المفروغ منه.\nوقيل: هو إشارة إلى ما قال - صلى الله عليه وسلم -:\n\"أول ما خلق الله القلم، فقال له: اجر بما هو كائن إلى يوم القيامة\".\nوقيل: الأمر ههنا إشارة إلى الإبداع، وهو اختراع الشيء من غير أصل.\nلا في زمان ولا في مكان، ولا بآلة، وذلك يعبر عنه بالأمر.\nوعلى ذلك قوله: ﴿أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ﴾⟪7:54⟫."}, {"a": [48], "v": 3, "p": 1265, "ev": 3, "ep": 1270, "sid": 1466, "t": "قوله تعالى: (إن الله لا يغفر أن يشرك به ويغفر ما دون ذلك لمن يشاء ومن يشرك بالله فقد افترى إثما عظيما (48)\n⟦3:1266⟧\nمعنى أن يشرك به: أن يديم الإنسان الشرك، فلا خلاف أن من لم يدم\nذلك بل أقلع عنه بالتوبة على الوجه الذي يجب يغفر له.\nلكن اختلف في قوله ﴿لِمَن يَشَآءُۚ﴾⟪4:48⟫ لكونه مجملا.\nفقال بعضهم: عنى به غير المشركين، فكأنه قيل:\nيغفر ما دون ذلك لغير المشركين، ففيه توعد أن المشرك\nمأخوذ بكل ذنب مع الشرك بخلاف المؤمنين، الذين قال لهم: ﴿إِن تَجۡتَنِبُواْ كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ﴾⟪4:31⟫.\nومنهم من قال: عنى به التائب بدلالة قوله تعالى: ﴿إِنَّ رَحۡمَتَ ٱللَّهِ قَرِيبٞ مِّنَ ٱلۡمُحۡسِنِينَ﴾⟪7:56⟫.\nوقول من قال: ﴿لِمَن يَشَآءُۚ﴾⟪4:48⟫ يقتضي ذلك، أن فيما دون الكفر\nما يغفر، وهو الصغائر، وفيه ما لا يغفر وهو الكبائر، وإلا لم\nيكن لقوله: ﴿لِمَن يَشَآءُۚ﴾⟪4:48⟫ فائدة، فليس بصحيح لأن قوله:\n﴿مَا دُونَ ذَٰلِكَ﴾⟪4:48⟫ عام للذنوب صغائرها وكبائرها، والمغفور له هو\n⟦3:1267⟧\nالذي جعله خاصا منهما، فيقتضي أن ما دون الشرك كله يغفر.\nلكن يغفر لبعض دون بعض، واشتراط (لمن يشاء) لئلا يقرر\nأن ذلك عام للمشرك وغير المشرك، فصار قوله: ﴿لِمَن يَشَآءُۚ﴾⟪4:48⟫\nعبارة عن غير المشركين.\nوقولهم: إن الكبائر دون الشرك لو صح غفرانها لم يثبت فيها اللعن\nولا الحد على وجه النكال ليس بشيء.\nفليس في ذكر اللعن ما يقتضي أن لا يغفر لصاحبه.\nوأما النكال في الدنيا فتعلقهم به جهل أو تجاهل، لأن موضوع النكال\nليكون قمعا للمنكل به عن معاودته وقمع غيره عن أن يحذو\nحذوه، وليس ذلك من عقوبة الآخرة في شيء، بل قد قيل هو\nمسقط لعقوبة الآخرة، لقوله - صلى الله عليه وسلم -:\n\"الحدود كفارات لأهلها \"،\n⟦3:1268⟧\nألا ترى أنه قد يحد التائب مع أن العقوبة في الآخرة قد سقطت\nعنه بالتوبة؟!\nوما رواه جابر أنا كنا نمسك عن الاستغفار لأهل الكبائر حتى نزل قوله: ﴿إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ﴾⟪4:48⟫ الآية. دلالة على فساد قولهم، وما قالوه بأن هذا من أخبار الآحاد فلا يقبل فيما هو من باب التدين والعلم، فإن أخبار\n⟦3:1269⟧\nالآحاد ترد فيما تعافه العقول الصحيحة، وقد علم أن العفو\nمن باب الإحسان الذي حثنا عليه العقل والشرع، وبتحريه يصير\nالعبد من الصديقين والشهداء والصالحين.\nوالافتراء: يقال في القول والفعل كالصدق والكذب.\nبل الافتراء وإن تعورف في القول فهو بالفعل أولى.\nوكذا الاختلاق، لأنهما من فريت الأديم وخلقته.\nومعنى الإثم العظيم هو الذي إذا اعتبر بالآثام كان\n⟦3:1270⟧\nأكثرها عقوبة."}, {"a": [49], "v": 3, "p": 1270, "ev": 3, "ep": 1271, "sid": 1471, "t": "قوله تعالى: (ألم تر إلى الذين يزكون أنفسهم بل الله يزكي من يشاء ولا يظلمون فتيلا (49)\nالتزكية ضربان: أحدهما: بالفعل، وهو أن يتحرى الإنسان ما فيه تطهير بدنه، وذلك يصح أن ينسب إلى العبد تارة نحو قوله: ﴿قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا﴾⟪91:9⟫ وإلى من يؤمر بفعله، نحو قوله: ﴿خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةٗ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا﴾⟪9:103⟫.\nوالثاني: بالقول، وذلك بالإخبار عنه بذلك، ومدحه به.\nومحظور على الإنسان أن يفعل ذلك بنفسه، لا بالشرع فقط.\nبل بمقتضى العقل، من غير داع إلى ذلك، ولما قالت اليهود\nوالنصارى ﴿نَحۡنُ أَبۡنَٰٓؤُاْ ٱللَّهِ وَأَحِبَّٰٓؤُهُۥۚ﴾⟪5:18⟫، ﴿وَقَالُواْ لَن يَدۡخُلَ ٱلۡجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوۡ نَصَٰرَىٰۗ﴾⟪2:111⟫ ذمهم الله تعالى بذلك، وذم من\n⟦3:1271⟧\nيفعل فعلهم، وحظر أن يمدح الإنسان نفسه، بل أن يزكي غيره\nإلا على وجه مخصوص، فالتزكية في الحقيقة هي الإخبار\nعما ينطوي عليه الإنسان، ولا يعرف ذلك إلا الله تعالى.\nولهذا قال: ﴿بَلِ ٱللَّهُ يُزَكِّي مَن يَشَآءُ﴾⟪4:49⟫\nونبه بقوله: ﴿وَلَا يُظۡلَمُونَ فَتِيلًا﴾⟪4:49⟫ أن تزكيته ليست لضرب من الميل.\nفهو منزه عن كبير الظلم وصغيره.\nوالفتيل: هو الخيط الذي في شق النواة.\nوقيل: هو ما فتل من الوسخ بين الأصبعين.\nتشبيها بالفتيلة هيئة وصغر قدر،"}, {"a": [50], "v": 3, "p": 1272, "ev": 3, "ep": 1272, "sid": 1473, "t": "قوله تعالى: (انظر كيف يفترون على الله الكذب وكفى به إثما مبينا (50)\nذكر ذلك تعظيما لزعمهم ﴿نَحۡنُ أَبۡنَٰٓؤُاْ ٱللَّهِ وَأَحِبَّٰٓؤُهُۥۚ﴾⟪5:18⟫\nونبه بقوله: ﴿وَكَفَىٰ بِهِۦٓ إِثۡمٗا مُّبِينًا﴾⟪4:50⟫ أنه لايخفى كونه مأثما."}, {"a": [51], "v": 3, "p": 1272, "ev": 3, "ep": 1274, "sid": 1473, "t": "قوله تعالى: (ألم تر إلى الذين أوتوا نصيبا من الكتاب يؤمنون بالجبت والطاغوت ويقولون للذين كفروا هؤلاء أهدى من الذين آمنوا سبيلا (51)\nالجبت والطاغوت: في الأصل اسمان لصنمين، ثم صارا يستعملان\nفي كل باطل، ولذلك قيل: ما عبد من دون الله فهو طاغوت،\n⟦3:1273⟧\nولذلك فسر مرة بالصنم، ومرة بالشيطان، ومرة بالسحر، ومرة بكل\nمعظم من دون الله، وإنما ذكرهم بإيتاء نصيب من الكتاب تقبيحا\nلفعلهم، فمن جحد الحق مع معرفته به فهو أقبح فعلا وأعظم مأثما.\nوعنى بالذين كفروا مشركي العرب، حيث زعموا أنهم أهدى\nسبيلا من المسلمين، ومعنى قوله: (للذين) أي لأجلهم وفيهم،\n⟦3:1274⟧\nولهذا قال: هؤلاء ولم يقل: أنتم، وباقي الآية مفهوم."}, {"a": [53], "v": 3, "p": 1274, "ev": 3, "ep": 1275, "sid": 1475, "t": "قوله تعالى: (أم لهم نصيب من الملك فإذا لا يؤتون الناس نقيرا (53)\nالنقير: النقطة في ظهر النواة، وقيل: حبة فيها، وقيل:\nما نقر بالأصبع من الحصى، وكيفما كان فذلك كالفتيل\nوالقطمير فيما يضرب به المثل في الشيء الحقير، و (إذن) متى\nتقدمه حرف عطف فقد يترك إعماله، نحو قوله:\n⟦3:1275⟧\n﴿وَإِذٗا لَّا يَلۡبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلٗا﴾⟪17:76⟫.\nوعطف بالجملة على ما قبله بأم على تقدير كلام قبله.\nكأنه قيل: أهم أولى بالنبوة أم لهم نصيب من الملك.\nفيلزم الناس طاعتهم؟\nوقيل: أم بدل على معنى بل.\nوكذلك قيل في قوله تعالى: (الم (1) تنزيل الكتاب لا ريب فيه من رب العالمين (2) أم يقولون افتراه)، ونبه على بخلهم مع تمكنهم من المال."}, {"a": [54, 55], "v": 3, "p": 1275, "ev": 3, "ep": 1278, "sid": 1476, "t": "قوله تعالى: (أم يحسدون الناس على ما آتاهم الله من فضله فقد آتينا آل إبراهيم الكتاب والحكمة وآتيناهم ملكا عظيما (54)\nالحسد: غم يلحق الإنسان بسبب خير ناله مستحقه،\n⟦3:1276⟧\nقال ابن عباس: عنى بالناس ههنا النبي - صلى الله عليه وسلم -\nوقال قتادة: عنى به العرب، وقيل: عنى به المسلمين.\nوالفضل: ما خص به - صلى الله عليه وسلم - من النبوة.\nوإنما ذكر الناس - وإن قصد به مخصوصا -\nلأنهم إذا كرهوا ما آنزل على النبي - صلى الله عليه وسلم -\nفقد حسدوا الناس بما\n⟦3:1277⟧\nأولاهم كمال الإنسانية، وفيه تنبيه أنهم خارجون عن جملتهم.\nونبه أنه كما آتاهم الفضل فقد آتى آل إبراهيم ما ذكره.\nوأنه لو كان ما آتى محمدا يقتضي أن يحسد عليه فما آتى\nآل إبراهيم أولى بذلك، فيكون الكتاب والحكمة راجعا\nإلى ما أوتي موسى وعيسى عليهما السلام وغيرهما.\nويجوز أن يكون الكتاب والحكمة إشارة إلى ما أوتي النبي\n- صلى الله عليه وسلم -، ويكون فيه تنبيه.\nوما أنعم الله عليه هو إنعام عليهم إذ كان معرضا لانتفاعهم به.\nوالملك العظيم قيل: ملك سليمان، والأصح أنه عام.\nوأنه لم يعن به تملك الغير، بل هو عام في ذلك.\nوفيما اقتضى تملك الإنسان على نفسه\nوقمعه لحرصه وسائر شهواته، فذلك هو أعظم الملكين.\nوقوله: (فمنهم) قال مجاهد: أي من أهل الكتاب من آمن بمحمد\n- صلى الله عليه وسلم -.\nوقيل: منهم من آمن بإبراهيم من أمته، كما أنكم في أمر\n⟦3:1278⟧\nمحمد كذلك تنبيها أنه ليس في صد بعضهم عن محمد توهين\nلأمره، كما لم يكن في صد بعضهم عن إبراهيم توهين لأمره.\nوفي قوله: ﴿وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا﴾⟪4:55⟫ تنبيه أنهم وإن لم تلحقهم\nالعقوبة معجلة فقدكفاهم ما أعد لهم من سعير جهنم."}, {"a": [56], "v": 3, "p": 1278, "ev": 3, "ep": 1280, "sid": 1479, "t": "قوله تعالى: (إن الذين كفروا بآياتنا سوف نصليهم نارا كلما نضجت جلودهم بدلناهم جلودا غيرها ليذوقوا العذاب إن الله كان عزيزا حكيما (56)\nإصلاؤهم بالنار: جعلهم صلى لها، كقوله:\n⟦3:1279⟧\n﴿وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُۖ﴾.\nوقوله: ﴿كُلَّمَا نَضِجَتۡ جُلُودُهُم بَدَّلۡنَٰهُمۡ جُلُودًا غَيۡرَهَا﴾⟪4:56⟫ فيه قولان؟\nأحدهما: أنه يعاد ذلك الجلد بعينه على صورة أخرى.\nكقولك: بدلت الخاتم قرطا، إذا خالفت بين الصورتين.\nالثاثي: أنه يخلق لهم جلود إذا نضجت لهم جلود، فالعذاب والألم يصل إلى ما تحت الجلود من الروح وغيرها بوساطة الجلود كوصول النار إليه بوساطة سرابيل القطران المذكور في قوله: ﴿سَرَابِيلُهُم مِّن قَطِرَانٖ وَتَغۡشَىٰ وُجُوهَهُمُ ٱلنَّارُ﴾⟪14:50⟫، وتبيين ذلك أن الجلد واللحم متى تعريا\n⟦3:1280⟧\nعن الروح لم يلحقهما ألم، فعلم أن المقصود بالألم ما فيه الروح\nدون الجلود والأغشية، ولكون البدن للروح كالثياب للبدن.\nيعبر بالثياب عن البدن كقوله: ﴿وَثِيَابَكَ فَطَهِّرۡ﴾⟪74:4⟫\nوقول الشاعر:\nثياب بني عوف طهارى نقية. . . . . . . . . . . . . . .\nوقو له تعالى: ﴿لِيَذُوقُواْ ٱلۡعَذَابَۗ﴾⟪4:56⟫ استعارة متناهية في وصول\nالألم إلى الباطن، وعلى ذلك استعير لهم الطعام في قوله: ﴿وَطَعَامٗا ذَا غُصَّةٖ وَعَذَابًا أَلِيمٗا﴾⟪73:13⟫ ذكر مع الذوق المس في قوله: ﴿ذُوقُواْ مَسَّ سَقَرَ﴾⟪54:48⟫ تنبيها أن ذلك استعارة، ونبه بقوله: ﴿إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمٗا﴾⟪4:56⟫\nأن لا سبيل إلى الامتناع عليه والفرار من عذابه.\nوبقوله: (حكيما) أن ذلك تقتضيه الحكمة."}, {"a": [57], "v": 3, "p": 1281, "ev": 3, "ep": 1282, "sid": 1482, "t": "قوله تعالى: (والذين آمنوا وعملوا الصالحات سندخلهم جنات تجري من تحتها الأنهار خالدين فيها أبدا لهم فيها أزواج مطهرة وندخلهم ظلا ظليلا (57)\nقد تقدم الكلام في ذكر الإيمان والأعمال الصالحة، ومعنى الجنات\nالتي تجري من تحتها الأنهار، وذكر الخلود فيها أبدا، والأزواج\nالمطهرة، فأما قوله: ﴿ظِلّٗا ظَلِيلًا﴾⟪4:57⟫ فإشارة إلى النعمة، والنعمة\nالدائمة، كما يقال: أنا في ظلك، وكما روي في الخبر: \"سبعة\nيظلهم الله في ظل عرشه يوم لا ظل إلا ظله \"، والظليل إشارة\n⟦3:1282⟧\nإلى تمام وجود معنى الظلية فيه، كقولهم: شمس شمامس.\nوليل أليل."}, {"a": [58], "v": 3, "p": 1282, "ev": 3, "ep": 1286, "sid": 1483, "t": "قوله تعالى: (إن الله يأمركم أن تؤدوا الأمانات إلى أهلها وإذا حكمتم بين الناس أن تحكموا بالعدل إن الله نعما يعظكم به إن الله كان سميعا بصيرا (58)\nقال ابن جريج: نزل ذلك في عثمان بن طلحة رضي الله عنه\nلما أخذ منه رسول الله - صلى الله عليه وسلم - مفتاح الكعبة.\nفأمره الله أن يرده\n⟦3:1283⟧\nإليه، وقال: زيد ومكحول: نزل في ولاة الأمر.\nقال ابن عباس: في كل مؤتمن على شيء، وهو أصح. فإنه عام،\n⟦3:1284⟧\nوقد عظم الله أمر الأمانة، وبين أنه من خصائص الإنسان، حيث قال\nتعالى: ﴿إِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ﴾⟪33:72⟫\nوقال - صلى الله عليه وسلم -:\n\"ثلاث يؤدين إلى البر والفاجر: الأمانة، والعهد، وصلة الرحم \".\nوتأدية الأمانة استحفاظ المستودع ووضعه حيث ما أمر بوضعه فيه.\nوليس ذلك في رد الوديعة فقط، بل في جميع ما خص الله تعالى به الإنسان من ماله ونفسه، فكل ذلك أمانة من الله عليه بحفظه حيث ما يجب حفظه، ويضعه حيث ما يجب وضعه، ولذلك قال تعالى:\n⟦3:1285⟧\n﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ﴾⟪9:111⟫.\nولهذا قال - صلى الله عليه وسلم -:\n\"كلكم راع، وكلكم مسئول عن رعيته \".\nوقد دخل في عمومه: النهي عن كتمان العلم عن أهله.\nوحفظه عن غير أهله، ولهذا قيل: لا تضع الحكمة في غير أهلها\nفتظلمها، ولا تمنعها أهلها فتظلمهم، وقد حث الله تعالى على\nحفظ جميع العدالات بهذه، وبيانه أن العدالة في شيئين:\nأحدهما: في حكم يختص به الإنسان في نفسه، أو فيما بينه وبين\n⟦3:1286⟧\nغيره، وقد تناول ذلك قوله: ﴿إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تُؤَدُّواْ ٱلۡأَمَٰنَٰتِ إِلَىٰٓ أَهۡلِهَا﴾⟪4:58⟫، والثاني: في حكم يتولاه ألإنسان بين اثنين، وذلك\nقد تناوله في قوله: ﴿وَإِذَا حَكَمۡتُم بَيۡنَ ٱلنَّاسِ أَن تَحۡكُمُواْ بِٱلۡعَدۡلِۚ﴾⟪4:58⟫.\nثم قال: ﴿إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓۗ﴾⟪4:58⟫ تنبيها أن من سمع وعظه، واستعمله فقد فاز فوزا عظيما، ونبه بذكر السمع على حكم الأول على علمه بما يحدث الإنسان به نفسه، وبالبصر على حكم مشاهدته لما يتعاطاه."}, {"a": [59], "v": 3, "p": 1286, "ev": 3, "ep": 1290, "sid": 1487, "t": "قوله تعالى: (يا أيها الذين آمنوا أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم فإن تنازعتم في شيء فردوه إلى الله والرسول إن كنتم تؤمنون بالله واليوم الآخر ذلك خير وأحسن تأويلا (59)\nقيل: أولو الأمر الأمراء على عهد رسول الله - صلى الله عليه وسلم -.\nولذلك قال: ﴿فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ﴾⟪4:59⟫.\nوقيل: الأمراء في زمانه وبعده، ورده إليهما إنما هو إلى حكمهما.\nوحمل الشيعة ذلك\n⟦3:1287⟧\nعلى الأئمة من أهل البيت.\nوقال أبو هريرة: أولو الأمر أمراء السرايا.\nوقد روي أن النبي - صلى الله عليه وسلم - قال:\n\"من أطاعني فقد أطاع الله، ومن عصاني فقد عصى الله \".\nوقال ابن عباس: هم أهل الفقه والدين، وأهل طاعة الله الذين يأمرون بالمعروف وينهون عن المنكر.\nوكل هذه الأقوال صحيح، ومراد بالآية، ووجه ذلك\n⟦3:1288⟧\nأن أولي الأمر الذين يرتدع بهم الناس أربعة:\nالأول: الأنبياء، وحكمهم على ظواهر الخاصة والعامة وبواطنهم.\nوالثاني: الولاة، وحكمهم على ظاهر الخاصة والعامة دون باطنهم.\nوالثالث: الحكماء، وحكمهم على بواطن الخاصة.\nوالرابع: الوعاظ، وحكمهم على بواطن العامة، وعلى ذلك\nقوله: ﴿وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِينَ يَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡۗ﴾⟪4:83⟫.\nوقوله: ﴿فَإِن تَنَٰزَعۡتُمۡ فِي شَيۡءٖ﴾⟪4:59⟫\nقيل: هو خطاب للكافة.\nوقيل: بل لأولي الأمر منهم إذا وقع تنازع فيما بينهم في حكم،\n⟦3:1289⟧\nوقوله: ﴿فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ﴾⟪4:59⟫\nأي راجعوه بالسؤال في زمانه، وإلى كتاب الله وسنة نبيه بعده.\nوقال الأصم: معناه ما لا تعلمونه فقولوا: الله ورسوله أعلم.\nوهذا إن أراد به فيما لا سبيل لبشر إلى معرفته.\nأو فيما لا يبلغ إلى مرتبته فصحيح.\nوإن أراد أنه يقتصر على ذلك مع وجود سبيل إليه.\nأو احتياجه إليه فرضى بأخس منزلة.\nوقد تعلق بذلك مثبتوه أيضا، وقالوا: جعل الله\nأحكامه ثلاثة أقسام: مثبتا بالكتاب، ومثبتا بالسنة، وعليهما\nدل قوله: ﴿أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ﴾⟪4:59⟫، ومثبتا بالاجتهاد\nوالاستنباط، وهو ما يرد إلى الكتاب وسنة نبيه، قال:\nفالرد إليهما هو البناء علي حكمهما، وهذا هو القياس الشرعي، والرد\n⟦3:1290⟧\nعلى هذا محمول على فائدة غير مستفادة من قوله: ﴿أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ﴾⟪4:59⟫.\nقوله: ﴿إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ﴾⟪4:59⟫ أي من شرط الإيمان أن لا يتخطى\nمرسوم الله تعالى ومرسوم نبيه - صلى الله عليه وسلم -، فمن\nترك ذلك فقد ترك الإيمان.\nوقوله: ﴿وَأَحۡسَنُ تَأۡوِيلًا﴾⟪4:59⟫\nقال مجاهد: أحسن جزاء وعاقبة.\nوقال قتادة والسدي: عاقبة.\nوقال الزجاج: أحسن من تأويلكم من غير رد إلى كتاب الله والسنة."}, {"a": [60], "v": 3, "p": 1291, "ev": 3, "ep": 1293, "sid": 1492, "t": "قوله تعالى: (ألم تر إلى الذين يزعمون أنهم آمنوا بما أنزل إليك وما أنزل من قبلك يريدون أن يتحاكموا إلى الطاغوت وقد أمروا أن يكفروا به ويريد الشيطان أن يضلهم ضلالا بعيدا (60)\nقد تقدم أن الزعم مطية الكذب. والطاغوت مبني من\nطغى، كالجالوت من جال، وقيل: كل ما عبد من دون الله\nفهو طاغوت، وقيل: هو اسم لكل ما شغل عن الله من نحو\n⟦3:1292⟧\nالهوى ونحوه، وعليه نبه بقوله - صلى الله عليه وسلم -:\n\"الهوى إله معبود\"، ثم تلا: ﴿أَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلۡمٖ﴾⟪45:23⟫.\nوروي أن. ذلك نزل في رجل من المنافقين دعاه يهودي في خصومة إلى حكم\nالنبي - صلى الله عليه وسلم -، فقال المنافق: بل نتحاكم إلى الكاهن، وقيل: بل قال إلى الصنم، وهو أنهم كانوا يحضرونه ويضربون بالقداح ، فمن خرج قدحه حكم له، ونبه بقوله: ﴿وَيُرِيدُ ٱلشَّيۡطَٰنُ أَن يُضِلَّهُمۡ ضَلَٰلَۢا بَعِيدٗا﴾⟪4:60⟫\n⟦3:1293⟧\nبعد قوله: ﴿يُرِيدُونَ أَن يَتَحَاكَمُوٓاْ إِلَى ٱلطَّٰغُوتِ﴾⟪4:60⟫\nأن إرادتهم بهذا الفعل مقرونة بإرادة الشيطان أن يضلهم ضلالا\nبعيدا، وأن بفعلهم ذلك يجد الشنيطان إلى ضلالهم سبيلا، وهذا\nتنبيه أنه لولا اتباعهم الشهوات وإخلالهم بالعبادات لما وجد\nالشيطان إليهم سبيلا، كما قال: ﴿وَمَا كَانَ لِيَ عَلَيۡكُم مِّن سُلۡطَٰنٍ﴾⟪14:22⟫\nالآية. والضلال البعيد هو الذي يصعب الرجوع عنه.\nوهو المشار إليه بقوله تعالى: ﴿أُوْلَٰٓئِكَ يُنَادَوۡنَ مِن مَّكَانِۭ بَعِيدٖ﴾⟪41:44⟫."}, {"a": [61], "v": 3, "p": 1293, "ev": 3, "ep": 1294, "sid": 1494, "t": "قوله تعالى: (وإذا قيل لهم تعالوا إلى ما أنزل الله وإلى الرسول رأيت المنافقين يصدون عنك صدودا (61)\nالصد: كالسد: إلا أن السد بحائل محسوس.\nوالصد بحائل في النفس من إرادة أو كراهة، ونحو ذلك من الحوايل.\n⟦3:1294⟧\nوالآية من تمام القصة الأولى، ومن الأشياء التي\nدعوا إليها فصدوا عنها آيات القتال، كقوله تعالى: ﴿فَإِذَآ أُنزِلَتۡ سُورَةٞ مُّحۡكَمَةٞ وَذُكِرَ فِيهَا ٱلۡقِتَالُ رَأَيۡتَ ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يَنظُرُونَ إِلَيۡكَ نَظَرَ ٱلۡمَغۡشِيِّ عَلَيۡهِ مِنَ ٱلۡمَوۡتِۖ فَأَوۡلَىٰ لَهُمۡ﴾⟪47:20⟫.\nوالتأكيد بالمصدر كقوله: ﴿يَصُدُّونَ عَنكَ صُدُودٗا﴾⟪4:61⟫\n﴿وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكۡلِيمٗا﴾⟪4:164⟫ هو أن الفعل له حقيقة\nما وتجوز به كاستعماله في بعض ما وضع له أو في غير ما وضع\nله، وإذا أريد أن يبين أنه مستعمل على وجهه وحقيقته ضم إليه\nمصدره. هذا فائدته."}, {"a": [62], "v": 3, "p": 1294, "ev": 3, "ep": 1297, "sid": 1495, "t": "قوله تعالى: (فكيف إذا أصابتهم مصيبة بما قدمت أيديهم ثم جاءوك يحلفون بالله إن أردنا إلا إحسانا وتوفيقا (62)\nروي أن ذلك المنافق مع اليهودي لما تحاكما إلى النبي - صلى الله عليه وسلم - فحكم لليهودي قال المنافق: لا أرضى بذلك.\nثم \"تحاكما إلى أبي بكر فكان كمثل، ثم تحاكما إلى عمر.\nفقال المنافق: كان من الأمر كذا، فقال له عمر: قفا لأخرج إليك.\nفدخل وأخذ السيف فخرج وقتله،\n⟦3:1295⟧\nفشكوا إلى النبي - صلى الله عليه وسلم - فلما سأله؟\nقال عمر: قتلته لأنه رد حكمك، فقال - صلى الله عليه وسلم -:\n\"أنت الفاروق \".\nثم جاء أصحابه إلى النبي - صلى الله عليه وسلم - يحلفون\nكذبا إن أردنا إلا إحسانا وتوفيقا .\nإن قيل: ما المسئول عنه بقوله: كيف؟\nوما الذي يتعلق به إذا؟ وعلى ماذا عطف قوله: ﴿ثُمَّ جَآءُوكَ﴾⟪4:62⟫؟\nوأي مصيبة أريدت بذلك: التي نالتهم في الدنيا\nبقتل صاحبهم أم شيء منتظر؟\nقيل: أما المسئول عنه فمحذوف كما حذف في قوله: ﴿فَكَيۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۭ بِشَهِيدٖ﴾⟪4:41⟫، وبقوله: ﴿فَكَيۡفَ إِذَا جَمَعۡنَٰهُمۡ﴾⟪3:25⟫\nوتقديره: كيف حالهم ومقالهم؟\nوأما إذا فإنه يتعلق بذلك المضمر.\nوأما قوله: ﴿ثُمَّ جَآءُوكَ﴾⟪4:62⟫ فمعطوف على قوله: ﴿أَصَٰبَتۡهُم مُّصِيبَةُۢ﴾⟪4:62⟫،\n⟦3:1296⟧\nوتقديره: كيف حالهم إذا أصابتهم مصيبة بما قدمت أيديهم\nبارتكابهم وبمجيئهم من بعد إليك حالفين كذبا: إننا ما أردنا إلا\nإحسانا وتوفيقا، وأما المراد بالصيبة المذكورة فما ينالهم في الآخرة\nمن العذاب والحسرة والندامة، فيقول: إن تألموا من هذه فكيف\nتألمهم إذا أصابتهم مصيبة في الآخرة، وقد تقدم أن الإحسان\nهو الفضل الموفي على العدالة، والتوفيق: موافقة أمر الله\nوالرضا بقضائه، وهما غاية ما يراد من الإنسان، فنبه أنهم\n⟦3:1297⟧\nيدعودن هاتين الحالتين كذبا."}, {"a": [63], "v": 3, "p": 1297, "ev": 3, "ep": 1300, "sid": 1498, "t": "قوله تعالى: (أولئك الذين يعلم الله ما في قلوبهم فأعرض عنهم وعظهم وقل لهم في أنفسهم قولا بليغا (63)\nالقول البليغ: إذا، اعتبر بنفسه، فهو ما يجمع أوصافا ثلاثة:\nأن يكون صوابا في موضع لغته، وطبقا للمعنى المقصود به.\nلا زائدا عليه ولا ناقصا عنه، وصدقا في نفسه.\nوإذا اعتبر بالمقول له والقائل فهو الذي يقصد به قائله الحق.\nويجد من المقول له قبولا، ويكون وروده في\nالموضع الذي يجدر أن يورد فيه، فكل قول اجتمع فيه هذه\nالأوصاف فهو البليغ من كل وجه، وقول العرب: أحمق بلغ\nوبلغ، إذا بلغ مع حماقته حاجته، وقد يقال ذلك للمتناهى في\nحماقته، وقول من قال: القول البليغ هو أن يقال لهم:\n⟦3:1298⟧\nإن، أظهرتم ما في أنفسكم قتلناكم.\nوقول من قال: خوفهم بمكاره تنزل بهم في الدنيا والآخرة.\nفإشارة إلى بعض مقتضنى الآية، ونبه بقوله: ﴿أُوْلَٰٓئِكَ ٱلَّذِينَ يَعۡلَمُ ٱللَّهُ مَا فِي قُلُوبِهِمۡ﴾⟪4:63⟫\nعلى أمرين: أحدهما: نهي الناس أن يخفوا في أنفسهم غير الحق.\nوالثاني: أن يقتصر من كل واحد في أحكام الدنيا على ما يظهره.\nوترك الفحص عما يضمره، وفي قوله تعالى:\n⟦3:1299⟧\n(فأعرض عنهم) الآية، قولان:\nأحدهما: أنه أمر أن يقابل جماعتهم بهذه المعاملة الثلاث، من الإعراض عنهم، والتجافي عن ذمهم، وقول المعروف لهم.\nوالقول الثاني: أن كل واحد من الأحكام الثلاثة إلى فرقة على حدة، فالإعراض عمن يظهر الإسلام، لقوله - صلى الله عليه وسلم -:\n\" أمرت أن أقاقل الناس. . . \" الخبر.\n⟦3:1300⟧\nوالوعظ للأوساط. والقول البليغ للخواص. وهؤلاء الفرق\nالثلاث هم المذكورون بقوله: (وأما إن كان من أصحاب اليمين (90) فسلام لك من أصحاب اليمين (91).\nإلى آخر القصة."}, {"a": [64], "v": 3, "p": 1300, "ev": 3, "ep": 1302, "sid": 1501, "t": "قوله عز وجل: (وما أرسلنا من رسول إلا ليطاع بإذن الله ولو أنهم إذ ظلموا أنفسهم جاءوك فاستغفروا الله واستغفر لهم الرسول لوجدوا الله توابا رحيما (64)\nاستغفار الإنسان وتوبته يمكن أن يقال: هما في الحقيقة واحد، لكن\nاختلافهما بحسب اعتبارهما بغيرهما؟\nفالاستغفار يقال إذا استعمل في الفزع إلى الله تعالى، وطلب الغفران منه. والتوبة تقال إذا اعتبر بترك العبد ما لا يجوز فعله وفعل ما يجب.\nولا يكون الإنسان طالبا في الحقيقة لغفران الله إلا بإتيان\nالواجبات، وترك المحظورات، ولا يكون تائبا إلا إذا حصل\nعلى هذه الحالة، ويمكن أن يقال: الاستغفار مبدأ التوبة.\nوالتوبة تمام الاستغفار، ولهذا قال تعالى:\n⟦3:1301⟧\n﴿وَٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ﴾⟪11:90⟫.\nوأما استغفار الرسول - صلى الله عليه وسلم - لهم فهو\nالدعاء لهم، وهو ضرب من الشفاعة في الدنيا، وعلى ذلك\nحث تعالى بقوله: ﴿وَصَلِّ عَلَيۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنٞ لَّهُمۡۗ﴾⟪9:103⟫\nوالقصد بالآية لما قتل عمر ذلك المنافق، وكان ظاهره الإسلام\nووقع شبهة على من لم يتصور حاله، بين تعالى جواز قتله\nبألطف حجة، دل عليه بقوله: ﴿وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذۡنِ ٱللَّهِۚ﴾⟪4:64⟫، وبيانه أن خصوصية الرسول عليه الصلاة والسلام طاعته فيما يحكم به، تنبيها أن من لم يطعة لم يؤمن به، وهذا المقتول لم يطعه.\nفإذا لم يؤمن به، ومن لم يؤمن برسوله من غير مانع فمستحق للقتل.\nفإذا هذا المنافق\n⟦3:1302⟧\nمستحق للقتل.\nإن قيل: لم قال ﴿جَآءُوكَ فَٱسۡتَغۡفَرُواْ ٱللَّهَ وَٱسۡتَغۡفَرَ لَهُمُ ٱلرَّسُولُ﴾⟪4:64⟫\nولم يقل: فاستغفرت؟\nقيل: تنبيها على مقتضى فضيلة الرسالة، وأن بفضيلتها يستحق قبول شفاعته وموقع استغفاره."}, {"a": [65], "v": 3, "p": 1302, "ev": 3, "ep": 1307, "sid": 1503, "t": "قوله تعالى: (فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في أنفسهم حرجا مما قضيت ويسلموا تسليما (65)\nالمشاجرة: المنازعة، وأصله من اختلاط الأشجار.\nوشجر بيته رفعه بالشجر، والشجار اسم ما يرفع به من الشجر.\nومصدر شاجره أي نازعه، والتشاجر يكون بالأبدان بالحرب\nوباللسان في القول.\nوالحرج: الضيق، وأصله الحرجة الملتفة\n⟦3:1303⟧\nمن الأشجار، وسأل عمر رضي الله عنه أعرابيا عن الحرج.\nفقال: هو أن يلتف الشجر ويناشب فلا يصل إليه شيء.\nقال: فكذلك قلب الكافر محظور عليه الإيمان، ممتنع امتناع هذه\nالحرجة.\nوقوله: (لا) في أول الكلام هو رد لزعمهم: أنا آمنا.\nفقال: لا، أي ما آمنوا، ولفظة: لا، قد ينفى به الفعل\nالماضي إذا لم يذكر معه الفعل، كقوله: أخرجت؟ فتقول: لا.\nويجوز أن يكون نفيا للثاني، لكن حذف معه الفعل اكتفاء\nبما ذكر من بعده، وعلى الوجهين قول الشاعر:\nلا وأبيك أبنت العامري. . . لا يدعي القوم أني أفر\n⟦3:1304⟧\nوالآية من تمام القصة المتقدمة، وقول من قال: نزل في حاطب\nابن أبي بلتعة حيث اختصم مع الزبير بن العوام في سبب\n⟦3:1305⟧\nالماء إلى النبي عليه الصلاة والسلام، فحكم للزبير.\nفسخط حاطب، فإنه يجوز أن شأن نزوله هذه الحال، ويجوز\n⟦3:1306⟧\nأن يكون قد نزل فيهما، وبين تعالى أن التوقف في إلزام حكمك\nفيما وقع بينهم من المشاجرة هو مخرج لهم عن الإيمان، وإنما\nيكون حصول الإيمان الحقيقي بعد أن لا يروا ضيق صدر في جميع\nما تحكم به، (ويسلموا تسليما): أي يسلمون ظواهرهم\nوبواطنهم، والتسليم منا هو الإسلام المأمور به في قوله:\n﴿ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ﴾⟪3:102⟫،\n⟦3:1307⟧\nوهو المسئول في قوله: ﴿تَوَفَّنِي مُسۡلِمٗا﴾⟪12:101⟫."}, {"a": [66], "v": 3, "p": 1307, "ev": 3, "ep": 1309, "sid": 1508, "t": "قوله عز وجل: (ولو أنا كتبنا عليهم أن اقتلوا أنفسكم أو اخرجوا من دياركم ما فعلوه إلا قليل منهم ولو أنهم فعلوا ما يوعظون به لكان خيرا لهم وأشد تثبيتا (66)\nنبه تعالى على عقيدتهم ووهن إيمانهم.\nوأن المؤمن في الحقيقة من يسلم تسليما كما تقدم ذكره.\nوبين أن هؤلاء لم يؤمنوا، بعد، بحيث لو أوجب عليهم قتل\nأنفسهم أو الإخلال بدورهم لكان أكثرهم ممتنعين، ثم أخبر أنهم\nلو قبلوا الموعظة لكان ذلك خيرا لهم وأشد تثبيتا، أي أشد\nلتحصيل عملهم ونفي جهلهم، وقيل: أثبت لأعمالهم واجتناء\nثمرة فعالهم، وأن يكونوا بخلاف من قيل فيهم:\n⟦3:1308⟧\n﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾⟪25:23⟫\nوروي أن نفرا من أصحاب النبي - صلى الله عليه وسلم - لما نزلت هذه الآية قالوا: لو أن ربنا تعالى فعل لفعلنا، فالحمد لله الذي عافانا فعرف رسول الله - صلى الله عليه وسلم - أن ذلك منهم حق فقال:\n\"والذي نفس محمد بيده للإيمان أثبت في قلوب المؤمنين من الجبال الرواسي \"، وروي أنه أشار إلى عبد الله بن رواحة، وقال: \"إنه من القليل \".\nوروي أنه\n⟦3:1309⟧\nقال: \"إن ثابت بن قيس من القليل الذي استثنى الله تعالى\"."}, {"a": [67, 68], "v": 3, "p": 1309, "ev": 3, "ep": 1309, "sid": 1510, "t": "قوله عز وجل: (وإذا لآتيناهم من لدنا أجرا عظيما (67) ولهديناهم صراطا مستقيما (68)\nبين أنهم لو قبلوا الموعظة لجمع لهم بين خير الدنيا والآخرة، وذلك هو المعني بقوله: ﴿وَٱلَّذِينَ ٱهۡتَدَوۡاْ زَادَهُمۡ هُدٗى﴾⟪47:17⟫\nوالصراط المستقيم الذي وعدهم هو الذي حرض على سؤاله في قوله: ﴿ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ﴾⟪1:6⟫.\nوإنما قال: ﴿مِّن لَّدُنَّآ﴾⟪4:67⟫ لأنه تعالى لا يكاد ينسب إلى نفسه من النعم إلا ما\nكان أجلها قدرا وأعظمها خطرا، نحو: وروحنا."}, {"a": [69], "v": 3, "p": 1309, "ev": 3, "ep": 1314, "sid": 1510, "t": "قوله عز وجل: (ومن يطع الله والرسول فأولئك مع الذين أنعم الله عليهم من النبيين والصديقين والشهداء والصالحين وحسن أولئك رفيقا (69)\n⟦3:1310⟧\nأصل الرفق: التفكر في الأمر والتثبت، ويضاده الخرق.\nوقيل ذلك للمعاونة، ومنه المرفق والمرفق، والرفقة\nللجماعة المعاونة في السفر، والرفيق كالصديق، ويقالان للواحد والجمع.\nوالفرق بين الرسول والنبي أن الرسول أخص.\nفكل رسول نبي وليس كل نبي رسولا.\nفإن الرسول يختص بمن جعله واسطة بينه وبين عباده\nلتبيين أحكام بوحي مسموع عن ملك.\nوالنبي قد يقال لمن يجدد على الناس شريعة من تقدمه\nوإن كان يوحى إليه بإلهام أو منام.\nوأخص من الرسول أولو العزم من الرسل.\nوقد تقدم ذكر ذلك،\n⟦3:1311⟧\nوقد قسم الله تعالى المؤمنين في هذه الآية أربعة أقسام.\nوجعل لهم أربعة منازل، بعضها دون بعض، وحث كافة الناس\nأن لا يتأخروا عن منزل واحد منهم:\nالأول: هم الأنبياء: الذين تمدهم قوة إلهية.\nومثلهم كمن يرى الشيء عيانا من قريب.\nولذلك قال تعالى في صفة نبينا عليه الصلاة والسلام:\n﴿أَفَتُمَٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ﴾⟪53:12⟫.\nوالثاني: الصديقون: وهم الذين يتاخمون الأنبياء في المعرفة.\nومثلهم كمن يرى الشيء عيانا من بعيد.\nوإياه عنى أمير المؤمنين حيث قيل: هل رأيت الله؟ فقال:\nما كنت لأعبد شيئا لم أره، ثم قال: لم تره العيون بشواهد العيان.\nولكن رأته القلوب بحقائق الإيمان.\nوالثالث: الشهداء: وهم الذين يعرفون الشيء بالبراهين، ومثلهم كمن يرى الشيء في المرآة من مكان قريب، كحال حارثة، حيث قال: كأني\n⟦3:1312⟧\nأرى عرش ربي. وإياه قصد النبي - صلى الله عليه وسلم -، حيث قال: \"اعبد الله كأنك تراه \".\nوالرابع: الصالحون: وهم الذين يعلمون الشيء بإقناعات وتقليدات للراسخين في العلم، ومثلهم كمن يرى\n⟦3:1313⟧\nالشيء من بعيد في مرآة، وإياه قصد النبي - صلى الله عليه وسلم - بقوله: \"اعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك \".\nأي كن من الشهداء بما تكتسبه من العلم والعمل الصالح.\nفإن لم تكن منهم فكن من الصالحين.\nوتقدير الآية على وجهين:\nأحدهما: من أطاع الله ورسوله منكم ألحقه الله بالذين يقدمهم ممن أنعم عليهم من الفرق الأربع في المنزلة والثواب.\nالنبي بالنبي والصديق بالصديق، والشهيد بالشهيد والصالح بالصالح،.\nوالثاني: أن قوله: ﴿مِّنَ ٱلنَّبِيِّـۧنَ﴾⟪4:69⟫ يتعلق بقوله: ﴿وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ﴾⟪4:69⟫، وقوله: ﴿ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم﴾⟪4:69⟫ إشارة إلى الملأ الأعلى، ثم قال: ﴿وَحَسُنَ أُوْلَٰٓئِكَ رَفِيقٗا﴾⟪4:69⟫ ويبين ذلك قول النبي عليه الصلاة والسلام في\nحين الموت: \"اللهم ألحقني بالرفيق الأعلى\"، وهذا\n⟦3:1314⟧\nظاهر، وهذه الآية كأنها مردودة إلى ما تقدم من قوله: ﴿أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ﴾ فلما تمم القصة بين ما لمطيعهم من الثواب\nبهذه الآية، وروي أن رجلا من الأنصار جاء إلى النبي - صلى الله عليه وسلم - كئيبا، فقال: يا رسول الله نحن نغدو عليك ونروح ننظر في وجهك\nونجالسك، وغدا ترفع إلى النبيين فلا نصل إليك. فسكت النبي\n- صلى الله عليه وسلم - فجاءه جبريل عليه السلام بهذه الآية."}, {"a": [70], "v": 3, "p": 1315, "ev": 3, "ep": 1316, "sid": 1516, "t": "قوله عز وجل: ﴿ذَٰلِكَ ٱلۡفَضۡلُ مِنَ ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ عَلِيمٗا﴾⟪4:70⟫.\nلما كانت نعم الله تعالى ضربين: دنيويا ولا يصل إلينا من الله إلا\nبواسطة، أو وسائط كالمال والجاه وغير ذلك. وأخرويا يصل\nإلينا - لا بواسطة، بين الله تعالى أن ذلك الفضل الذي ذكره بقوله:\n﴿أَنۡعَمَ ٱللَّهُ عَلَيۡهِم﴾⟪4:69⟫ هو من الله علي الإطلاق، فنسب إلى نفسه\nتفخيما لأمره، كما قال: ﴿مَٰلِكِ يَوۡمِ ٱلدِّينِ﴾⟪1:4⟫.\nوقوله: ﴿فَنَفَخۡنَا فِيهَا مِن رُّوحِنَا﴾ ونحو ذلك، فخبر الابتداء على\nهذا هو (من الله)، ويجوز أن يكون مبتدأ، و (الفضل)\nخبره، كقولك: ذاك هو الرجل،، وهذا هو المال، تنبيها على\nكماله، فإن الشيء إذا عظم أمره يوصف باسم جنسه، كقوله:\n﴿وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ ٱلۡحَيَوَانُۚ﴾⟪29:64⟫.\nويكون قوله: ﴿مِنَ ٱللَّهِۚ﴾⟪4:70⟫ في موضع الحال، أو خبر ابتداء مضمر، ثم قال:\n⟦3:1316⟧\n﴿وَكَفَىٰ بِٱللَّهِ عَلِيمٗا﴾⟪4:70⟫ تنبيها أنه هو أعرف بمقادير الفضل، وقد حكم\nبأن الفضل المعتد به هو ذاك."}, {"a": [71], "v": 3, "p": 1316, "ev": 3, "ep": 1319, "sid": 1517, "t": "قوله تعالى: (يا أيها الذين آمنوا خذوا حذركم فانفروا ثبات أو انفروا جميعا (71)\nحذركم: قيل: معناه أسلحتكم، وقيل: معناه احذروا.\nوالثبة للجماعة المنفردة، قال الشاعر:\nوقد أعدو على ثبة كرام.\n⟦3:1317⟧\nومنه ثبت على فلان إذا ذكرت متفرق محاسنه، وتصغر ثبة\nعلى ثبية، وتجمع على ثبات وثبين، وأما ثبة الحوض فوسطه\nالذي يثوب إليه الماء.\nوأصل النفر: الانزعاج، وذلك على ضربين:\nانزعاج عن الشيء، وانزعاج إليه، وعلى ذلك\nالفزع: فزع عن الشيء، وفزع إليه.\nقال: إذا فزعوا طاروا إلى مستغيثهم.\nوالنفر: للجماعة الذين ينفرون إلى حرب، والمنافرة في\n⟦3:1318⟧\nالحكم أصله أن يتحاكم اثنان - أيهما أفضل نفرا.\nقال ابن عباس: هذه الآية نسخها قوله تعالى ة ﴿وَمَا كَانَ ٱلۡمُؤۡمِنُونَ لِيَنفِرُواْ كَآفَّةٗۚ فَلَوۡلَا نَفَرَ مِن كُلِّ فِرۡقَةٖ مِّنۡهُمۡ طَآئِفَةٞ﴾⟪9:122⟫\nوإنما عنى بذلك التخصيص والتنبيه أن ليس يلزم النفر جماعتهم، ونحو\nذلك قوله: ﴿ٱنفِرُواْ خِفَافٗا وَثِقَالٗا﴾⟪9:41⟫ الآية، أنها في الحرب\nوفي الحقيقة فيها وفي المبادرة إلى جميع ثواب الله.\nوقوله: ﴿خُذُواْ حِذۡرَكُمۡ﴾⟪4:71⟫ نحو ﴿وَٱتَّقُواْ ٱللَّهَ﴾.\nوقوله: ﴿فَلَا تَخۡشَوُاْ ٱلنَّاسَ وَٱخۡشَوۡنِ﴾⟪5:44⟫، ﴿فَلَا تَخَافُوهُمۡ وَخَافُونِ﴾⟪3:175⟫.\nونحو قوله: (فانفروا)، ﴿سَابِقُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا كَعَرۡضِ ٱلسَّمَآءِ وَٱلۡأَرۡضِ﴾⟪57:21⟫.\n⟦3:1319⟧\nوفي قوله: (ثبات) أو (جميعا) تنبيه أنه لا يجب أن يعتبر طالب الحق كثرة مصاحبيه وقلتهم، نحو قوله ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ عَلَيۡكُمۡ أَنفُسَكُمۡۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهۡتَدَيۡتُمۡۚ﴾⟪5:105⟫."}, {"a": [72, 73], "v": 3, "p": 1319, "ev": 3, "ep": 1321, "sid": 1520, "t": "قوله تعالى: (وإن منكم لمن ليبطئن فإن أصابتكم مصيبة قال قد أنعم الله علي إذ لم أكن معهم شهيدا (72) ولئن أصابكم فضل من الله ليقولن كأن لم تكن بينكم وبينه مودة يا ليتني كنت معهم فأفوز فوزا عظيما (73)\nالبطء والريث والأناة والثبات واللبث تتقارب،، ولكن الثبات يقتضي الزوال، ويقالان متعديين عن بطء تقول يبطئن أي يثبط غيره.\nوقيل: يكثر هو التثبيط في نفسه.\nبين تعالى أن قوما بعد فيكم ومنكم أي يتأخرون عن الحرب أو\nيؤخرون غيرهم، فإن أصابكم جهد وبلاء من الدنيا يسرون\nبتأخرهم عنكم، ويريدون أن ذلك نعمة نالتهم، تنبيها أنهم لا\nيعدون النعمة إلا من أعراض الدنيا،\n⟦3:1320⟧\n﴿وَلَئِنۡ أَصَٰبَكُمۡ فَضۡلٞ﴾⟪4:73⟫\nأي غنيمة وظفر يتحسرون على تأخرهم عنكم\nويحسدونكم على الفضل الذي أوتيتم.\nوفي قوله: ﴿كَأَن لَّمۡ تَكُنۢ بَيۡنَكُمۡ وَبَيۡنَهُۥ مَوَدَّةٞ﴾⟪4:73⟫ أقوال:\nالأول: أن يكون حكاية عنهم، أي ليقولن لمن يثبطكم:\nكأن لم تكن بينكم وبين محمد مودة، حيث لم يستعينوا\nبكم، ثم يقولون: ﴿يَٰلَيۡتَنِي كُنتُ مَعَهُمۡ﴾⟪4:73⟫ فيكون القول الأول\nمنهم إثارة للشر.\nوالقول الثاني منهم إظهارا للحسد.\nوالثاني: أن ذلك اعتراض متعلق بالجملة الأولى، وتقديره\nيقولون: قد أنعم الله على إذ لم أكن معهم شهيدا، كأن لم تكن\nبينكم وبينهم مودة، فأخر ذلك، وذلك مستقبح في العربية،\n⟦3:1321⟧\nفإنه لا يفصل بين بعض الجملة التي دخل في إثباتها، وتقديره:\nيقول: يا ليتني كنت معهم فأفوز فوزا عظيما كأن لم تكن، أي\nقولهم ذلك قول من ليس بينكم وبينهم مواصلة دينية.\nوذلك تنبيه على ضعف عقيدتهم، وسوء نيتهم.\nوقيل في قوله: ﴿قَدۡ أَنۡعَمَ ٱللَّهُ عَلَيَّ﴾⟪4:72⟫ منة منه على قومه من المنافقين.\nإذ يثبطهم عن الخروج، وإنه قد ظهر ثمرة نصيحته في قوله: ﴿يَٰلَيۡتَنِي﴾⟪4:73⟫\nإيهام للذين قالوا لهم: إن ذلك كان بإيثار الرسول لمن أخرجهم\nمن دونه، وفي الآيتين تنبيه أن عامة الناس لا يعدون إلا أعراض\nالدنيا، فيفرحون بما ينالهم منها، ولا من المحن إلا مصائبها.\nفيتألمون بما يصيبهم منها، وذلك قوله: ﴿فَأَمَّا ٱلۡإِنسَٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّيٓ أَكۡرَمَنِ﴾⟪89:15⟫ الآية."}, {"a": [74], "v": 3, "p": 1322, "ev": 3, "ep": 1323, "sid": 1523, "t": "قوله تعالى: (فليقاتل في سبيل الله الذين يشرون الحياة الدنيا بالآخرة ومن يقاتل في سبيل الله فيقتل أو يغلب فسوف نؤتيه أجرا عظيما (74)\nالذين يشرون: أي يبيعون وهو المعني بقوله: ﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ﴾⟪9:111⟫\nوقوله: (الذين) هو فاعل (يقتل)، والمفعول محدوف.\nوقيل قوله: (فليقاتل) أمر لمن يبطئ وهم الذين يشرون.\nومعناه يشترون، فحثوا على ترك ما حكي عنهم في الآية المتقدمة.\nوأن يجاهدوا في سبيل الله،\n⟦3:1323⟧\nفإن قيل: لم لم يقتصر على قوله: ﴿وَمَن يُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ﴾⟪4:74⟫ بل عقبه\nبقوله: ﴿فَيُقۡتَلۡ أَوۡ يَغۡلِبۡ﴾⟪4:74⟫؟\nقيل: تنبيها أن من تحرى القتال سواء قتل أو قتل، غلب أوغلب فقد وقع أجره على الله، وتقدير الكلام: يقتل أو يقتل أو يغلب، لئلا يتوهم السامع أن التزام الغلبة والبراح من المعركة في كل حال سائغ.\nألا ترى أنه قد عظم التولي عن القتال بقوله: (فلا تولوهم الأدبار (15) ومن يولهم يومئذ دبره) الآية، ومنهم من جعل المقاتلة في سبيله\nمجاهدة للنفس، نحو ما روي عنه عليه الصلاة والسلام:\n\"جاهدوا أهواءكم \".\nوجعل سبيل الله هو المذكور في قوله:\n﴿ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ﴾⟪16:125⟫.\nوالأجر العظيم ثواب الآخرة، ووصفه بالعظيم اعتبارا بعرض الدنيا.\nكما وصف الثمن بالقليل."}, {"a": [75], "v": 3, "p": 1323, "ev": 3, "ep": 1325, "sid": 1524, "t": "قوله عز وجل: (وما لكم لا تقاتلون في سبيل الله والمستضعفين من الرجال والنساء والولدان الذين يقولون ربنا أخرجنا من هذه القرية الظالم أهلها واجعل لنا من لدنك وليا واجعل لنا من لدنك نصيرا (75)\n⟦3:1324⟧\nقال ابن عباس: القرية الظالم أهلها: مكة.\nوقال: كنت من الولدان، وإني كنت من المستضعفين فيها.\nفإن قيل: ما الفرق بين المولى والنصير؟\nقيل: المولى هو الذي يتولى حفظ الشيء في كل حال.\nوالنصير هو الذي. ينصره إذا حزبه أمر، فكان الولي\nهو النصير في كل حال، والنصير هو المولى حال دون حال.\nومن هذا الوجه قال بعض المفسرين: أريد بالولي النبي وبالنصير\nالملائكة، وقال بعضهم: جعل الله وليهم النبي - صلى الله عليه وسلم -\n⟦3:1325⟧\nونصيرهم التابع الذي ولاه عليهم، ونبه بعطف المستضعفين\nعلى أن الحماية عليهم هو المقاتلة في سبيل الله، وأن\nنصرتهم نصرته تعالى، وعطف قوله: (المستضعفين) على\nالله تعالى تعظيما، كما قال تعالى: ﴿وَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ﴾⟪4:1⟫، فعطف (والأرحام) على لفظ (الله) تعظيما لأمره."}, {"a": [76], "v": 3, "p": 1325, "ev": 3, "ep": 1327, "sid": 1526, "t": "قوله تعالى: (الذين آمنوا يقاتلون في سبيل الله والذين كفروا يقاتلون في سبيل الطاغوت فقاتلوا أولياء الشيطان إن كيد الشيطان كان ضعيفا (76)\nالمقاتل في سبيل الله يتناول المحارب بالسيف والمدافع عن الدين بالقول، والمنازع لهوى النفس ولوساوس الشيطان،\n⟦3:1326⟧\nوقد تقدم أن الطاغوت عام في كل ما شغل عن الله.\nوالمراد به وبالشيطان واحد، ونبه أن من قاتل في سبيل الله فهو وليه.\nومن قاتل في سبيل الطاغوت فهو ولي الشيطان.\nونبه بقوله ﴿إِنَّ كَيۡدَ ٱلشَّيۡطَٰنِ كَانَ ضَعِيفًا﴾⟪4:76⟫\nعلى ضعف أوليائه، ووصف كيده بالضعف إذ لا بطش له.\nوإنما سلطانه بين باطل، ولضعفه في الحقيقة قال تعالى حاكيا عنه:\n﴿وَمَا كَانَ لِيَ عَلَيۡكُم مِّن سُلۡطَٰنٍ إِلَّآ أَن دَعَوۡتُكُمۡ فَٱسۡتَجَبۡتُمۡ لِيۖ﴾⟪14:22⟫ الآية.\nقال بعض المفسرين: وصف كيد الشيطان بالضعف عند مقاتلة\nالإنسان في سبيل الله، فكأنه قيل: إن كيد الشيطان كان ضعيفا على\n⟦3:1327⟧\nمن يقاتل في سبيل الله، وقال بعضهم: وصف كيد الشيطان\nبالضعف لضعف نصرة أوليائه بالإضافة إلى نصرة الله المؤمنين.\nوقال بعضهم: الذين يقاتلون في سبيل الطاغوت هم الذين\nينكرون ما تدعو إليه الحجج."}, {"a": [77], "v": 3, "p": 1327, "ev": 3, "ep": 1329, "sid": 1528, "t": "قوله تعالى: (ألم تر إلى الذين قيل لهم كفوا أيديكم وأقيموا الصلاة وآتوا الزكاة فلما كتب عليهم القتال إذا فريق منهم يخشون الناس كخشية الله أو أشد خشية وقالوا ربنا لم كتبت علينا القتال لولا أخرتنا إلى أجل قريب قل متاع الدنيا قليل والآخرة خير لمن اتقى ولا تظلمون فتيلا (77)\nروي أن قوما استأذنوا النبي - صلى الله عليه وسلم -\nفي قتال المشركين قبل أن فرض عليهم القتال، فلم ياذن الرسول عليه الصلاة والسلام، فلما فرض ذلك عليهم وهم بالمدينة\nصعب على قوم منهم ذلك،\n⟦3:1328⟧\nفقالوا: ﴿لِمَ كَتَبۡتَ عَلَيۡنَا ٱلۡقِتَالَ لَوۡلَآ أَخَّرۡتَنَآ إِلَىٰٓ أَجَلٖ قَرِيبٖۗ﴾⟪4:77⟫\nأي: هلا؟ وهذا يجوز أن يكون قد تفوهوا به، ويجوز أنهم اعتقدوه:\nوقالوه في أنفسهم، فحكى الله تعالى عنهم تنبيها أنهم لما استصعبوا\nذلك دل على استصعابهم أنهم غير واثقين بأحوالهم ولا مقدمين\nلما يعتقدونه من حسن أعمالهم، ومن نحو هذا التمني\nحذر في قوله: ﴿وَأَنفِقُواْ مِن مَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ أَحَدَكُمُ ٱلۡمَوۡتُ فَيَقُولَ رَبِّ لَوۡلَآ أَخَّرۡتَنِيٓ إِلَىٰٓ أَجَلٖ قَرِيبٖ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ﴾⟪63:10⟫.\nقال الحسن: هذا من صفة المؤمنين وما طبع\n⟦3:1329⟧\nعليه البشر من المخافة لا على إظهار العصيان وكراهة الحق.\nوقال غيره: بل هو من صفة المنافقين، الحراص على البقاء في\nالدنيا، وبين أنهم يخشون القتل منهم كخشية الموت من الله.\nوفيه تنبيه على جبنهم، وأنهم يخشون جيشهم الذين هم أمثالهم.\nوذلك نهاية الخوف، وعلى هذا دل الشاعر في ذم قوم وجبنهم\nحيث قال:\nالقوم أمثالكم لهم شعرء. . . في الرأس لا ينشرون إن قتلوا"}, {"a": [78, 79], "v": 3, "p": 1329, "ev": 3, "ep": 1343, "sid": 1530, "t": "قوله تعالى: (أينما تكونوا يدرككم الموت ولو كنتم في بروج مشيدة وإن تصبهم حسنة يقولوا هذه من عند الله وإن تصبهم سيئة يقولوا هذه من عندك قل كل من عند الله فمال هؤلاء القوم لا يكادون يفقهون حديثا (78) ما أصابك من حسنة فمن الله وما أصابك من سيئة فمن نفسك وأرسلناك للناس رسولا وكفى بالله شهيدا (79)\n⟦3:1330⟧\nالبروج: بيوت في قصور، وبها شبه بروج السماء، وسميت بها.\nوالمشيدة المبنية بالشيد والمزينة بها، ومن قال المشيدة المطولة فنظر منه\nإلى صفتها لا إلى حقيقة لفظها.\nوفقهت كذا أي علمته بالتفكر، ومنه سمي الفقه.\nوقد حمل البروج في الآية على\n⟦3:1331⟧\nالقصور، فيكون معناه كقول الأسود بن يعفر:\nولو كنت في غمران يحرس بابه. . . أراجيل أحبوش وأسود ألف\nإذا لأتتني حيث كنت منيتي. . . يخب به حاد لإثري قائف\nوحمل على بروج السماء، فيكون كقول زهير:\nومن هاب أسباب المنية يلقها. . . ولو نال أسباب السماءبسلم\nفعلى هذا وصف البروج بالمشيدة على طريق التشبيه، ولاعتبار\n⟦3:1332⟧\nذلك فسرت بالمطولة، والقصد بذلك إلى نحو ما قيل: والموت\nختم في رقاب العباد، وإلى نحو معناه قصد بقوله: ﴿قُلۡ فَٱدۡرَءُواْ عَنۡ أَنفُسِكُمُ ٱلۡمَوۡتَ﴾⟪3:168⟫.\nوقوله: ﴿فَمَالِ هَٰٓؤُلَآءِ ٱلۡقَوۡمِ لَا يَكَادُونَ يَفۡقَهُونَ حَدِيثٗا﴾⟪4:78⟫.\nأي لا يفهمون ما يوعظون به.\nوقيل: عنى بالحديث الحادثة من صروف الزمان.\nوالمعنى ما لهم لا يتدبرون ما يحدث حالا فحالا من صروف الزمن.\nكقوله تعالى: ﴿أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۗ﴾.\nوقوله: ﴿وَإِن تُصِبۡهُمۡ حَسَنَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ﴾⟪4:78⟫ الآية.\nقد طعن في ذلك قوم من الملحدة، وزعموا أن الآيتين متناقضتان.\nقالوا: ويدل على تناقضهما على وهم موردها ونسيانه في الوقت\n⟦3:1333⟧\nما قد سبق من كلامه، وإلا فأي ذي مسكة من العقل يقول:\n﴿كُلّٞ مِّنۡ عِندِ ٱللَّهِۖ﴾⟪4:78⟫، ثم يقول منكرا على ما قال ذلك ﴿مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ فَمِنَ ٱللَّهِۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٖ فَمِن نَّفۡسِكَۚ﴾⟪4:79⟫ فيثبت ما قد نفاه.\nوينقض ما قد بناه، هذا من طعن الملحدة، فأما أهل الشرع\nفقد تعلق بالآية الأولى الفرقة التي لقبها المعتزلة بالجبر.\nفقالوا: إن قوله: ﴿كُلّٞ مِّنۡ عِندِ ٱللَّهِۖ﴾⟪4:78⟫ عام يدل على أن الأفعال\nالظاهرة من العباد هي من الله، وتأولوا قوله تعالى: ﴿وَمَآ أَصَابَكَ مِن سَيِّئَةٖ فَمِن نَّفۡسِكَۚ﴾⟪4:79⟫ يقتضي أن لا ينسب فعل السيئة إلى الله تعالى\nبوجه، وجعلوا الحسنة والسيئة في الآية الأولى بمعنى\n⟦3:1334⟧\nالخصب والجدب والفقر والغنى، فأما طعن الملاحدة فظاهر\nالوهن، وذلك أن الحسنة والسيئة من الألفاظ المشتركة:\n⟦3:1335⟧\nكالحيوان الذي يقع على الإنسان والفرس والحمار، أو من\nالأسماء المختلفة كالعين، ولو أن قائلا قال: الحيوان متكلم.\nوالحيوان غير متكلم، وأراد بالأول الإنسان، وبالثاني الفرس\nوالحمار - لم يكن مناقضا، وكذا إذا قيل: العين في الوجه.\nوالعين ليست في الوجه، وأراد بالأولى الجارحة، وبالثانية عين\nالميزان أو السحاب، فكذلك الآية إذا أريد بالحسنة والسيئة في\nالآية الثانية غير الذي أريد بهما في الآية الأولى، وفي هذا\nقناعة لإبطال هزيل هذا المعترض، ثم إذا تؤمل مورد الكلام.\nوسبب نزول الآية بأن ألا تعلق لأحد الفريقين بالآية على وجه\nيثلج صدرا أو يزيل شكا، وسبب نزول ذلك أن قوما أسلموا\nذريعة إلى غنى ينالونه، وخصب يجدونه، وظفر يحصلونه، فكان\nإذا ناب أحدهم نائبة أو فاته محبوب، أو ناله مكروه أضاف سيئه\nإلى النبي عليه الصلاة والسلام متطيرا به، فقال تعالى: ﴿تُصِبۡهُمۡ سَيِّئَةٞ﴾⟪4:78⟫ أي خصب وسعة ﴿يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ﴾⟪4:78⟫\n⟦3:1336⟧\nأي جدب وفقر، لقالوا بك ونسبوها إليك.\nالحسنة والسيئة هاهنا هما المذكورتان في قوله: ﴿وَبَلَوۡنَٰهُم بِٱلۡحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ﴾⟪7:168⟫، وفي قوله: ﴿ثُمَّ بَدَّلۡنَا مَكَانَ ٱلسَّيِّئَةِ ٱلۡحَسَنَةَ﴾⟪7:95⟫.\nونحو هذه الآية قوله في قصة موسى عليه الصلاة والسلام: ﴿فَإِذَا جَآءَتۡهُمُ ٱلۡحَسَنَةُ قَالُواْ لَنَا هَٰذِهِۦۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَطَّيَّرُواْ بِمُوسَىٰ وَمَن مَّعَهُۥٓۗ أَلَآ إِنَّمَا طَٰٓئِرُهُمۡ عِندَ ٱللَّهِ﴾⟪7:131⟫،\n⟦3:1337⟧\nوفي قوله في صالح: ﴿قَالُواْ ٱطَّيَّرۡنَا بِكَ وَبِمَن مَّعَكَۚ قَالَ طَٰٓئِرُكُمۡ عِندَ ٱللَّهِۖ﴾⟪27:47⟫.\nإن قيل: ما الفرق بين قولك: هذا من عند الله، وهذا من الله.\nحتى قال في الأول: ﴿قُلۡ كُلّٞ مِّنۡ عِندِ ٱللَّهِۖ﴾⟪4:78⟫.\nوقال في الثاني: (فمن الله)؟\nقيل: قد قال بعضهم: إن قوله هذا من عند الله أعم.\nفإنه قد يقال: فيما كان برضاه وبسخطه وفيما يحصل.\nوقد أمر به ونهى عنه، ولا يقال: هو من الله إلا ما كان\nبرضاه وبأمره، وبهذا النظر قال عمر: إن أصبت فمن الله، وإن\nأخطأت فمن الشيطان، ثم ذكر تعالى ما يصيب الإنسان من\nثواب وعقاب ومحاب ومكاره، مما في سببه صنع بشر، فقال:\n﴿مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ فَمِنَ ٱللَّهِۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٖ فَمِن نَّفۡسِكَۚ﴾⟪4:79⟫.\nوعنى بالنفس المذكورة هاهنا المذكورة في قوله: ﴿إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ﴾⟪12:53⟫.\nومقتضى الآية كقوله: (من جاء بالحسنة فله خير منها وهم من فزع يومئذ آمنون (89) ومن جاء بالسيئة فكبت وجوههم في النار).\n⟦3:1338⟧\nوكقوله: ﴿وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٖ فَبِمَا كَسَبَتۡ أَيۡدِيكُمۡ وَيَعۡفُواْ عَن كَثِيرٖ﴾⟪42:30⟫، وعلى هذا فسر ابن عباس فقال: ﴿مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ﴾⟪4:79⟫: يوم بدر (فمن الله)، ﴿وَمَآ أَصَابَكَ مِن سَيِّئَةٖ﴾⟪4:79⟫: يوم حنين (فمن نفسك).\nإن قيل: كيف سمى العقاب سيئة، ومعلوم أنه في الحقيقة ليس بسيئة؟\nقيل: إن ذلك كقوله: ﴿وَجَزَٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ﴾⟪42:40⟫\nوقد تقدم مثل ذلك.\nإن قيل: إذا كان معنى الآية الثانية على\n⟦3:1339⟧\nما ذكرت في أنه أريد به الثواب والعقاب فهلا قال: ما أصابك\nمن حسنة وسيئة فمن نفسك، إذا كان مقتضى ثوابه وعقابه فعل\nالعبد؟\nقيل: إنما نسب الله تعالى الحسنة إلى نفسه في الثواب.\nتنبيها أنه سبب الخيرات، ولولاه لما حصل بوجه، فإنه يكسبه\nللعبد بإرادة من الله وأمر وحث وتوفيق، وأما السيئة وإن كانت\nبإرادة من الله عند قوم فليست بأمر منه ولا حث ولا توفيق، ومع\nذلك أدب بذكر ذلك عباده، ليراعوا فيما ينالهم نعمته عليهم.\nوينسبوا الحسنات إليه، ويعلموا أنه سبب كل خيرات، وأنه لولاه\nلما حصل منها شيء، وعلى هذا قوله عليه الصلاة والسلام:\n\"ما أحد يدخل الجنة إلا برحمة الله \".\nقيل: ولا أنت يا رسول الله؟ قال: \"ولا أنا\".\nوقال أمير المؤمنين عليه السلام: \"لا تخش إلا ذنبك، ولا ترج إلا ربك \"، إن قيل: ما الفرق بين الحسن\n⟦3:1340⟧\nوالحسنة والحسنى، والسيئ والسيئة والسوءى؟\nقيل: الحسن والحسنة يقالان في الأعيان والأحداث.\nولكن الحسنة إذا استعملت اسما فمتعارف في الأحداث دون الأعيان.\nوالحسنى لا تقال إلا في الأحداث، ومتى قيل: رجل سيئ\nفإنما يعني به المسيء.\nإن قيل: كيف قوبل الحسنة بالسيئة، وحقها أن تقابل بما يقتضي\nمعنى المسرة كما قال: مساءة ومسرة، وساءه وسره، ولا يقال في مقابلة ساء شيء من لفظ حسن؟\nقيل: الحسن لفظ عام كما تقدم، والحسنة والحسنى المقابل بهما السيئة والسوءى مخصوصان في الأفعال ولما كان كل\nفعل حسن يسر صاحبه، وكل فعل قبيح يسوء صاحبه، صار\nالقبح والسوء في الأفعال متلازمين فيصح أن يقال: الحسنة بالسيئة.\nإن قيل: من المخاطب في قوله: ﴿مَّآ أَصَابَكَ﴾⟪4:79⟫؟\n⟦3:1341⟧\nقيل: قال بعضهم: هو خطاب للنبي - صلى الله عليه وسلم -.\nومعناه للقوم الذين يبكتهم.\nوفي هذا النوع من الخطاب ضرب من التعريض، ولأجل قصد\nالتعريض في نحوه. قيل: إياك أعني واسمعي يا جارة.\nويدل على كونه خطابا له قوله من بعده: (وأرسلناك).\nوقيل: هو خطاب لكل إنسان، وذلك نحو قول القائل:\nأيها الإنسان وكلكم ذلك الإنسان.\nوقال ابن بحر: هو خطاب للفريق المذكور في قوله:\n﴿إِذَا فَرِيقٞ مِّنۡهُمۡ يَخۡشَوۡنَ ٱلنَّاسَ كَخَشۡيَةِ ٱللَّهِ﴾⟪4:77⟫\nقال: ولما كان لفظ الفريق والحي والجند مفردا صح أن يخاطب\n⟦3:1342⟧\nويخبر عنه بلفظ الواحدة تارة وبلفظ الجمع تارة، كلفظ كل ونحوه\nمن الألفاظ، وعلى هذا قول الشاعر:\nتفرق أهلانا بثين فمنهم. . . فريق أقام واستقل فريق\nوكل هذا كلام في مقتضى حكم اللفظ، فأما من حيث المعنى\nفالناس خاصهم وعامهم مراد بقوله: ﴿مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ فَمِنَ ٱللَّهِۖ﴾⟪4:79⟫\nإن قيل: ما وجه قوله: ﴿وَأَرۡسَلۡنَٰكَ لِلنَّاسِ رَسُولٗاۚ﴾⟪4:79⟫ بعد ذلك الكلام؟\nقيل: لما كان قوله: ﴿وَمَآ أَصَابَكَ مِن سَيِّئَةٖ فَمِن نَّفۡسِكَۚ﴾⟪4:79⟫\nإنذازا لهم، نبه بذلك أنه قد أزاح عللهم به، وأنهم متى عصوا فلا\nحجة لهم، إشارة إلى قوله: ﴿وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبۡعَثَ رَسُولٗا﴾⟪17:15⟫.\nوقوله: ﴿وَكَفَىٰ بِٱللَّهِ شَهِيدٗا﴾⟪4:79⟫ أي يشهد تعالى ما يفعله\n⟦3:1343⟧\nويفعلونه، ويشهد يوم القيامة، وكفى به مشاهدا وشاهدا."}, {"a": [80], "v": 3, "p": 1343, "ev": 3, "ep": 1344, "sid": 1544, "t": "قوله تعالى: (من يطع الرسول فقد أطاع الله ومن تولى فما أرسلناك عليهم حفيظا (80)\nنبه بذلك على حجة ظاهرة في وجوب طاعة نبيه.\nوبيانه أنه إذا كان طاعة الله واجبة، وطاعته لا تتم إلا بطاعته.\nلأن عامة أوامره لا سبيل إلى الوقوف عليها إلا من جهته.\nوما لا يتم الواجب إلا به فواجب كوجوبه، اقتضى\nذلك أن من أطاع رسول الله فقد أطاعه، فنبه بذلك على مقابله .\nوهو أن من عصى رسوله فقد عصى الله، وكالأمر بطاعة الله\nورسوله الأمر بالإيمان بهما في نحو قوله:\n⟦3:1344⟧\n﴿يُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦۚ﴾⟪24:62⟫، فكذلك الأمر باستجابته في قوله تعالى: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَجِيبُواْ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمۡ لِمَا يُحۡيِيكُمۡۖ﴾⟪8:24⟫.\nثم قال: ﴿فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗا﴾⟪4:80⟫ حثا على إبلاع ما ندب\nإليه من المأمور به في قوله: ﴿يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَۖ﴾⟪5:67⟫ وتنبيها أن ليس يعود عليك مضرة ما يفعلونه في أنفسهم.\nالمدلول عليه بقوله: ﴿وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ﴾.\nوقوله: ﴿إِنۡ عَلَيۡكَ إِلَّا ٱلۡبَلَٰغُۗ﴾⟪42:48⟫."}, {"a": [81], "v": 3, "p": 1344, "ev": 3, "ep": 1347, "sid": 1545, "t": "قوله عز وجل: (ويقولون طاعة فإذا برزوا من عندك بيت طائفة منهم غير الذي تقول والله يكتب ما يبيتون فأعرض عنهم وتوكل على الله وكفى بالله وكيلا (81)\nالمعني بقوله: (ويقولون)\n⟦3:1345⟧\nالذين يخشون الناس، وقد تقدم أن ذلك قيل من صفة المنافقين.\nوقيل من صفة الناس كافة.\nوالتبييت: كل فعل أو قول دبر بالليل.\nولأجله قيل: دع الرأي تبت، قال الشاعر:\nأتوني فلم أرض ما بيتوا. . . وكانوا أتوني بأمر نكر\nوقيل: اشتقاقه من بيت الشعر، أو البيت المبني، وهو الذي\nسوى من القول أو الفعل تسوية بيت شعر أو بيت شعر.\n⟦3:1346⟧\nونحو قوله: ﴿بَيَّتَ طَآئِفَةٞ﴾⟪4:81⟫ قوله: ﴿إِذۡ يُبَيِّتُونَ مَا لَا يَرۡضَىٰ مِنَ ٱلۡقَوۡلِۚ﴾⟪4:108⟫.\nقال الكلبي: التبييت في لغة طي: التبديل.\nومعنى الآية أنهم يبذلون من أنفسهم الطاعة قولا.\nفإذا خرجوا من عنده عليه الصلاة والسلام دبروا أن\nيفعلوا خلاف ما قالوا، (والله يكتب ما يبتتون)، أي يعلمه\nويحفظه) فيجازيهم به،\n⟦3:1347⟧\nوالكتابة هاهنا كالاستنساخ في قوله: ﴿إِنَّا كُنَّا نَسۡتَنسِخُ مَا كُنتُمۡ تَعۡمَلُونَ﴾⟪45:29⟫، ونسب ذلك إلى نفسه هنا، وإلى ملائكته في قوله: ﴿بَلَىٰ وَرُسُلُنَا لَدَيۡهِمۡ يَكۡتُبُونَ﴾⟪43:80⟫، وفي قوله: ﴿إِنَّ رُسُلَنَا يَكۡتُبُونَ مَا تَمۡكُرُونَ﴾⟪10:21⟫.\nوقد تقدم أنه تعالى قد ينسب فعل أوليائه إلى نفسه تنبيها على ارتضائه، وكونه آمرا نحو قوله: ﴿قُلۡ يَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ ٱلَّذِي وُكِّلَ بِكُمۡ﴾⟪32:11⟫.\nوقوله: ﴿ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا﴾⟪39:42⟫.\nوقوله: ﴿فَأَعۡرِضۡ عَنۡهُمۡ﴾⟪4:81⟫، ثم أمره بالتوكل عليه، وقد تقدم أن من التوكل ملازمة أوامره والانتهاء عن نواهيه، وأن لا يرجى ولا يخاف سواه، ونحو\nقوله: ﴿وَكَفَىٰ بِٱللَّهِ وَكِيلًا﴾⟪4:81⟫، قوله: ﴿وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓۚ﴾⟪65:3⟫."}, {"a": [82], "v": 3, "p": 1347, "ev": 3, "ep": 1351, "sid": 1548, "t": "قوله عز وجل: (أفلا يتدبرون القرآن ولو كان من عند غير الله لوجدوا فيه اختلافا كثيرا (82)\n⟦3:1348⟧\nالتدبير: النظر في دبر الأمور وتأملها، وقد يقال ذلك في تأمل الشيء بعد حصوله ومعرفة خيره من شره، وصلاحه من فساده، كقولك: تدبرت ما فعل فلان فوجدته سديدا، وأصل التدبر من الدبر، ومنه الدبور.\nوالدبر: المال الكثير الذي يخلفه الإنسان ويجعله عدة: إما لنفسه\nفي مستأنف عمره، أو لعقبه.\nإن قيل: كيف قال: ﴿وَلَوۡ كَانَ مِنۡ عِندِ غَيۡرِ ٱللَّهِ لَوَجَدُواْ فِيهِ ٱخۡتِلَٰفٗا كَثِيرٗا﴾⟪4:82⟫، وما من كلام لعل فيه من الاختلاف ما في القرآن، فما من آية إلا وقد اختلف فيها الناس؟\nقيل: لم يعن بالاختلاف ما يرجع إلى أحوال المختلفين، لاختلاف تصورهم لمعناه، أو اختلاف نظرتهم، ولا الاختلاف الذي يرجع إلى تباين الألفاظ والمعنى والإيجاز والبسط، وإنما قصد إلى معنى التناقض، وهو إثبات ما نفى أو نفي ما أثبت، نحو أن يقال: زيد خارج، زيد ليس بخارج.\nوالمخبر عنه والخبر والزمان والمكان فيهما واحد.\n⟦3:1349⟧\nادعت الملحدة - لعنهم الله - فيه التناقض، من نحو قوله: ﴿لَنَسۡـَٔلَنَّهُمۡ أَجۡمَعِينَ﴾⟪15:92⟫، وقوله: ﴿فَيَوۡمَئِذٖ لَّا يُسۡـَٔلُ عَن ذَنۢبِهِۦٓ إِنسٞ وَلَا جَآنّٞ﴾⟪55:39⟫.\nفذلك خبران قد اختلفا، إما في الزمان أو في المكان أو في\nالمخبر عنه، أو في الخبر، وهذا ظاهر.\nوقيل: معنى قوله: ﴿لَوَجَدُواْ فِيهِ ٱخۡتِلَٰفٗا كَثِيرٗا﴾⟪4:82⟫\nأن للإنسان هاديين: الشرع والعقل.\nكالأصل للشرع، فبين تعالى أن الذي أتاكم به من\nالشرع لو كان من عند غير الله لكان مقتضى العقل يخالفه، فلما\nلم يوجد بينه وبين العقل منافاة علم أنه من عند الله،\n⟦3:1350⟧\nفإن قيل: فقد ورد في الشرع أشياء يقتضي العقل خلافها؟\nقيل: كلا، فإن جميع ما ورد به الشرع لا ينفك من وجهين.\nإما شيء يحكم به العقل لكونه حسنا، مثل استعمال إله في الجملة.\nوعبادة الرب، أو يكون غير مهتد إلى معرفته لا أنه يستقبحه ، فيبين\n- الشرع حسنه، وذلك كأعداد الصلوات وهيئاتها وأركانها، في\nكونها عبادة على وجه دون وجه، وإما أن يأتي الشرع بشيء قد\nقضى العقل بكونه قبيحا فليس ذلك بموجود، وبعض الناس\nتصور أشياء ينفر الطبع منها لعادات جارية، أو اعتقادات فاسدة.\nولم يفرقوا بينه وبين حكم العقل، فظنوا أن العقل حكم بضد\nالشرع، كذبح البهائم.\nإن قيل: ما وجه تعلق هذه الآية بما تقدم؟\nقيل،: لما ذكر فيما تقدم أحوال الذين يتحاكمون إلى الطاغوت، ويتركون\nكتاب الله ورسوله، ويقاتلون في سبيل الطاغوت، وذكر الذين\nيخشون الناس ومقالهم فيما نالهم من حسنة أو سيئة.\nومخالفتهم في الطاعة، وكان كل ذلك منهم - لقلة تأملهم كتاب\nالله، وتقديرهم أن ما أمروا به في ثاني الحال من القتال مناقض لما\nأمر به قبل، من كف اليد وغير ذلك، بما يختلف لاختلاف\nالأحوال، نبههم تعالى في هذه الآية أن كل ذلك لقلة تدبرهم،\n⟦3:1351⟧\nوأنهم لو تدبروا لعلموا أن ذلك حق نزل عليهم من الله، كما\nقال: ﴿لَّا يَأۡتِيهِ ٱلۡبَٰطِلُ مِنۢ بَيۡنِ يَدَيۡهِ وَلَا مِنۡ خَلۡفِهِۦۖ﴾⟪41:42⟫."}, {"a": [83], "v": 3, "p": 1351, "ev": 3, "ep": 1355, "sid": 1552, "t": "قوله تعالى: (وإذا جاءهم أمر من الأمن أو الخوف أذاعوا به ولو ردوه إلى الرسول وإلى أولي الأمر منهم لعلمه الذين يستنبطونه منهم ولولا فضل الله عليكم ورحمته لاتبعتم الشيطان إلا قليلا (83).\nالاستنباط: استخراج الشيء من أصله، كاستنباط الماء من\nالبئر، والجوهر من المعدن، وذلك كالإثارة في إخراج التراب.\nواستعير للحديث، قال الشاعر:\n. . . يكفيك أثرى القول واستنباطي\nقال الفراء: يقال نبطه، قال: ومنه النبط لاستنباطهم\n⟦3:1352⟧\nالأرض عمارتها، والذين يستنبطونه منهم، قيل: هم أولو\nالأمر الذين لهم معرفة استنباطه، فيكون ذلك حثا على ترك\nمن لا يعلم لمن يعلم ليستنبط هو بمعرفته، فإذا عرف عرفهم\nما يجب تعريفه، وقيل: عنى بالذين يستنبطونه الذين يبينونه.\nويكون ذلك نهيا لهم عن الاستنباط بالتخمين والنظر، وحثا\nعلى رده إلى الرسول وإلى أولي الأمر منهم، وقد تقدم الكلام\nآنفا في أولي الأمر منهم، وقيل: سبب ذلك أن قوما كانوا إذا\n⟦3:1353⟧\nسمعوا من أفعال المؤمنين أو الكافرين ما فيه أمن أو خوف بادروا\nإلى إشاعته، قبل أن يتحققوا معناه.\nقال الفراء في سرايا النبي عليه الصلاة والسلام: وأنه كان إذا\nنفذ سرية بحث المنافقون عنها، فأشاعوا حديثها.\nقال الحسن: قد كان يفعل ذلك ضعفاء المسلمين، ويقولون\nأقوالا تخمينا، فنهوا عن ذلك، والآية تقتضي أن لا يقدم\nالإنسان على ما لا يتحقق جواز الإقدام عليه، ولا يقول إلا عن\nبصيرة، وعلى ذلك قوله تعالى: ﴿وَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ﴾⟪17:36⟫\nالآية، وقوله: ﴿وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَٱتَّبَعۡتُمُ ٱلشَّيۡطَٰنَ إِلَّا قَلِيلٗا﴾⟪4:83⟫، اختلف في قوله: ﴿إِلَّا قَلِيلٗا﴾⟪4:83⟫ عما استثنى، وذلك لاختلاف تصورهم لمعنى الفضل، فالأول عن الحسن\n⟦3:1354⟧\nوقتادة تقديره:، يستنبطونه منهم إلا قليلا.\nالرابع: لاتبعتم الشيطان إلا قليلا منكم.\nالخامس: لاتبعتم الشيطان إلا اتباعا قليلا.\nإن قيل: كيف القول الرابع والخامس، وقد علمنا أنه لولا\nفضله لاتبع الشيطان، بل ماكانوا يوحدون، فضلا عن\nأن يضلوا، فإنا لو تصورنا فضله مرتفعا لارتفع وجود الناس.\nبل وجود العالم؟\nقيل: إذا جرى الفضل على العموم فهو كما يقول، ومن أجله تحاشى من امتنع من أن يكون ذلك استثناء من قوله (لاتبعتم) فأما إذا جعلت فضله خاصا في هذا الموضع\n⟦3:1355⟧\nفمعناه صحيح، وبيان ذلك أن فضل الله وإن كان لا تحصى\nتفصيلاته، فالذي به هدانا إلى البلوغ إلى ثوابه فضلان: فضل\nالعقل وفضل الشرع، وعنى هاهنا بالفضل الشرع دون العقل.\nوبين أنه لولا ما أنعم به على الناس من رسوله وكتابه لما اهتدى\nمن خلائقه بالعقل المجرد إلا قليل من الناس، والقليل الذين لم\nيكونوا يتبعون الشيطان لولا فضل الله، هم الحكماء\nوالأولياء، الذين تتلو منزلتهم منزلة الأنبياء عليهم السلام.\nوهذا ظاهر."}];
